   ...mirror(s=>ball(s>0?'rHand':'lHand',[s*.328,.874,.005],.09,[1,1,1],'acc',.01)),{t:'aura',col:'acc',sh:.08},{t:'aura',col:'edge',sh:.05}]},
 void:{name:'VOID WEAVER',S:1.1,W:.9,hp:100,spd:.95,dmg:1,reach:1.05,aggr:.55,ideal:2.6,pw:['orb','horizon'],rm:{torso:.9},
  pal:{fill:[.22,.06,.34],fill2:[.5,.1,.6],edge:[1.1,.25,1.5],acc:[1.7,.5,1.9],eye:[2,1.2,2]},fx:{shim:.014,jit:0,rise:.3,orb:1.6},hot:[1.5,.4,1.8],
