 golem:{name:'STONE GOLEM',S:1.4,W:1.55,hp:170,spd:.62,dmg:1.5,reach:1.15,aggr:.5,ideal:1.7,pw:['boulder','quake'],rm:{torso:1.2,limb:1.25,hand:1.2,head:.8},
