ARCH.aton={name:'ATON RA',S:1.55,W:1.12,hp:230,spd:.8,dmg:1.55,reach:1.2,aggr:.85,ideal:1.8,pw:['visor','eclipse'],rm:{},
 pal:{fill:[.03,.03,.04],fill2:[.11,.1,.13],edge:[1.1,.12,.04],acc:[1.9,.95,.1],eye:[2.6,.18,.08]},fx:{shim:.004,jit:0,rise:.9},hot:[1.9,1.1,.15],
 body:()=>{
  const sp=(bone,c,r,sc)=>{sc=sc||[1,1,1];const o=ball(bone,c,r,sc,'fill',r*r*(sc[0]+sc[1]+sc[2])*3,0);o.spark=.05;return o;};
  const claw=(bone,s,j)=>cone(bone,[s*.345+s*j*.004,.835,.005+j*.03],[s*(.37+j*.006),.69,.005+j*.062],.02,'edge',.0022);
  return [
   sp('chest',[0,1.33,0],.205,[1.15,1,.95]),
   sp('spine',[0,1.0,0],.058,[1,1.15,1]),
   sp('head',[0,1.69,0],.1,[.95,1.05,1]),
   Object.assign(ball('head',[0,1.7,.075],.09,[.95,.3,.55],'eye',.012,0),{spark:1}),
   ...mirror(s=>sp('hips',[s*.15,.92,0],.095,[1,.95,1])),
   ...mirror(s=>sp('chest',[s*.37,1.45,0],.12)),
   ...mirror(s=>sp(s>0?'rArm':'lArm',[s*.28,1.22,0],.092,[1,1.2,1])),
   ...mirror(s=>sp(s>0?'rFore':'lFore',[s*.33,1.02,0],.075,[1,1.25,1])),
   ...mirror(s=>sp(s>0?'rHand':'lHand',[s*.345,.862,.005],.052,[.9,1.05,.9])),
   ...mirror(s=>[-1,0,1].map(j=>claw(s>0?'rHand':'lHand',s,j))).flat(),
   ...mirror(s=>sp(s>0?'rThigh':'lThigh',[s*.115,.69,0],.118,[1,1.25,1])),
   ...mirror(s=>sp(s>0?'rShin':'lShin',[s*.1,.33,0],.078,[1,1.45,1])),
   ...mirror(s=>({t:'cap',bone:s>0?'rFoot':'lFoot',a:[s*.1,.1,-.07],b:[s*.1,.045,.34],r0:.095,r1:.022,col:'fill',sh:.1,edgeBand:.1}))];},
 ex:()=>[{t:'aura',col:'acc',sh:.1},{t:'aura',col:'edge',sh:.08}]};

function buildCloud(key,N){
 const A=ARCH[key],pal=A.pal,rm=A.rm,S=[];
 const g=(grp)=>rm[grp]||1;
 if(A.body)A.body().forEach(e=>S.push(e));else{SEG.forEach(s=>S.push({t:'cap',bone:s[0],a:s[1],b:s[2],r0:s[3]*g(s[6]),r1:s[4]*g(s[6]),sh:s[5],col:'fill',edgeBand:.07,blend:s[0] in PARENT_OF&&s[6]!=='torso'?PARENT_OF[s[0]]:null}));
 SPH.forEach(s=>S.push({t:'sph',bone:s[0],c:s[1],r:s[2]*g(s[5]),sc:s[3],sh:s[4],col:'fill',head:s[0]==='head',spark:.02}));}
 A.ex().forEach(e=>S.push(e));
 let tot=0;S.forEach(s=>tot+=s.sh);
 const pos=new Float32Array(N*3),col=new Float32Array(N*3),skin=new Float32Array(N*4),ex=new Float32Array(N*3);
 let k=0;
 const fillC=pal.fill,f2=pal.fill2;
 for(const s of S){
  let cnt=Math.round(N*s.sh/tot);if(k+cnt>N)cnt=N-k;if(cnt<=0)continue;
  const bi=s.t==='aura'?BIDX.hips:BIDX[s.bone],rq=REST_Q[bi],bp=BONES[bi].pos,kind=s.t==='aura'?3:(s.kind||0);
  const b2=s.blend?BIDX[s.blend]:bi;
  let ax,ux,uy,uz,wx,wy,wz,L=0;
  if(s.t==='cap'){const d=V3.sub(s.b,s.a);L=V3.len(d)||1;ax=V3.scale(d,1/L);
   let h=Math.abs(ax[1])>.9?[1,0,0]:[0,1,0];const u=V3.norm(V3.cross(ax,h)),w=V3.cross(ax,u);[ux,uy,uz]=u;[wx,wy,wz]=w;}
  const colE=s.col&&pal[s.col]?pal[s.col]:null;
  for(let i=0;i<cnt&&k<N;i++,k++){
   let px,py,pz,edge=false,t=.5;
   if(s.t==='cap'&&A.poly&&s.col==='fill'&&A.poly.shape==='bolt'){t=Math.random();s._k=s._k||Array.from({length:7},()=>[rnd(-1,1),rnd(-1,1)]);const q=t*5,i0=Math.floor(q),fr=q-i0,k0=s._k[i0],k1=s._k[i0+1],rr=Math.max(s.r0,s.r1)*A.poly.k,ox=(k0[0]+(k1[0]-k0[0])*fr)*rr,oz=(k0[1]+(k1[1]-k0[1])*fr)*rr;
    px=s.a[0]+ax[0]*L*t+ux*ox+wx*oz+rnd(-.008,.008);py=s.a[1]+ax[1]*L*t+uy*ox+wy*oz+rnd(-.008,.008);pz=s.a[2]+ax[2]*L*t+uz*ox+wz*oz+rnd(-.008,.008);edge=fr<.1||fr>.9||Math.random()<.04;}
   else if(s.t==='cap'&&A.poly&&s.col==='fill'){const PD=polyData(A.poly.shape),n=Math.max(1,Math.round(L/(Math.max(s.r0,s.r1)*1.5))),j=Math.random()*n|0;t=(j+.5)/n;const rr=(s.r0+(s.r1-s.r0)*t)*A.poly.k,c=[s.a[0]+ax[0]*L*t,s.a[1]+ax[1]*L*t,s.a[2]+ax[2]*L*t],q=polySample(PD,c,rr,j*1.7+s.a[0]*5,A.poly.node);px=q[0];py=q[1];pz=q[2];edge=q[3];}
   else if(s.t==='cap'){t=Math.random();const th=Math.random()*6.2832,r=s.r0+(s.r1-s.r0)*t,c=Math.cos(th),sn=Math.sin(th);
    px=s.a[0]+ax[0]*L*t+(ux*c+wx*sn)*r;py=s.a[1]+ax[1]*L*t+(uy*c+wy*sn)*r;pz=s.a[2]+ax[2]*L*t+(uz*c+wz*sn)*r;
    const eb=s.edgeBand||0;edge=(eb&&(t<eb||t>1-eb))||Math.random()<.03;}
   else if(s.t==='sph'&&A.poly&&s.col==='fill'&&A.poly.shape!=='bolt'){const q=polySample(polyData(A.poly.shape),s.c,s.r*1.1,.6,A.poly.node*1.5,s.sc);px=q[0];py=q[1];pz=q[2];edge=q[3]||(s.head&&pz>s.c[2]+s.r*.5&&Math.random()<.5);}
   else if(s.t==='sph'){let vx,vy,vz,l;do{vx=rnd(-1,1);vy=rnd(-1,1);vz=rnd(-1,1);l=vx*vx+vy*vy+vz*vz;}while(l>1||l<1e-4);l=Math.sqrt(l);vx/=l;vy/=l;vz/=l;
    px=s.c[0]+vx*s.r*s.sc[0];py=s.c[1]+vy*s.r*s.sc[1];pz=s.c[2]+vz*s.r*s.sc[2];
    edge=Math.random()<(s.spark||.02);if(s.head&&vz>.55&&py>1.585&&py<1.64)edge=true;}
   else if(s.t==='ring'){const th=Math.random()*6.2832;px=s.c[0]+Math.cos(th)*s.r+rnd(-.012,.012);py=s.c[1]+rnd(-.012,.012);pz=s.c[2]+Math.sin(th)*s.r;edge=true;}
   else{const q=auraPt(A.aura);px=q[0];py=q[1];pz=q[2];edge=true;}
   const lc=Q.rotVecConj(rq,[px-bp[0],py-bp[1],pz-bp[2]]);
   pos[k*3]=lc[0];pos[k*3+1]=lc[1];pos[k*3+2]=lc[2];
   let w1=0;if(s.blend&&t<.18)w1=.5*(1-t/.18);
   skin[k*4]=bi;skin[k*4+1]=1-w1;skin[k*4+2]=b2;skin[k*4+3]=w1;
   let c=edge?(s.head&&px*0===0&&pz>0&&k%3===0?pal.eye:(colE&&s.t!=='cap'?colE:pal.edge)):(colE&&s.col!=='fill'?colE:null);
   if(!c){const m=Math.random()*(Math.sin(px*9+py*7)*.5+.5);c=[fillC[0]+(f2[0]-fillC[0])*m,fillC[1]+(f2[1]-fillC[1])*m,fillC[2]+(f2[2]-fillC[2])*m];}
   const br=.85+Math.random()*.45;col[k*3]=c[0]*br;col[k*3+1]=c[1]*br;col[k*3+2]=c[2]*br;
   ex[k*3]=Math.random();ex[k*3+1]=edge||kind===3?1:0;ex[k*3+2]=kind;
  }}
 // fill remainder in chest
 while(k<N){const s=S[2],bi=BIDX.chest,rq=REST_Q[bi],bp=BONES[bi].pos;const th=Math.random()*6.2832,t=Math.random();
  const lc=Q.rotVecConj(rq,[Math.cos(th)*.15,1.24+.18*t-bp[1],Math.sin(th)*.15]);
  pos[k*3]=lc[0];pos[k*3+1]=lc[1];pos[k*3+2]=lc[2];skin[k*4]=bi;skin[k*4+1]=1;skin[k*4+2]=bi;skin[k*4+3]=0;
  col[k*3]=fillC[0];col[k*3+1]=fillC[1];col[k*3+2]=fillC[2];ex[k*3]=Math.random();k++;}
 return {pos,col,skin,ex,count:N};
}

// ===== ENGINE: ECS / SHADERS / GL =====
const NSVG='http://www.w3.org/2000/svg';const $=id=>document.getElementById(id);
function World(){this.entities=[];this.systems=[];this.t=0;}
World.prototype.create=function(name){const e={id:this.entities.length,name:name,comps:{},add:function(c){this.comps[c.type]=c;return this;},get:function(t){return this.comps[t];}};this.entities.push(e);return e;};
World.prototype.addSystem=function(name,fn){this.systems.push({name:name,update:fn});};
function C(type,o){this.type=type;if(o)Object.assign(this,o);}
const GLSL_P='#ifdef GL_FRAGMENT_PRECISION_HIGH\nprecision highp float;\n#else\nprecision mediump float;\n#endif\n';
const VS_SKY='precision highp float;attribute vec2 aPos;uniform vec3 uR,uU,uF;uniform float uTy,uAsp;varying vec3 vDir;void main(){gl_Position=vec4(aPos,.999,1.);vDir=uF+uR*aPos.x*uTy*uAsp+uU*aPos.y*uTy;}';
const FS_SKY=GLSL_P+`varying vec3 vDir;uniform float uTime,uStars,uCity;uniform vec3 uZen,uHor,uSunCol,uSunDir,uMoonDir,uFog,uMtn;
float h1(float n){return fract(sin(n)*43758.5453);}
float h3(vec3 p){return fract(sin(dot(p,vec3(12.9898,78.233,37.719)))*43758.5453);}
float n1(float x){float i=floor(x),f=fract(x);f=f*f*(3.-2.*f);return mix(h1(i),h1(i+1.),f);}
float fb1(float x){return .5*n1(x)+.25*n1(x*2.07+3.1)+.125*n1(x*4.3+7.7)+.0625*n1(x*8.9+1.3);}
float n2(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);float a=h1(i.x+i.y*57.),b=h1(i.x+1.+i.y*57.),c=h1(i.x+(i.y+1.)*57.),d=h1(i.x+1.+(i.y+1.)*57.);return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}
float fb2(vec2 p){float s=0.,a=.5;for(int i=0;i<4;i++){s+=a*n2(p);p=p*2.03+17.;a*=.5;}return s;}
void main(){
 vec3 d=normalize(vDir);float y=d.y;float day=clamp(length(uSunCol),0.,1.);
 vec3 col=mix(uHor,uZen,pow(clamp(y,0.,1.),.45));
 float sd=dot(d,uSunDir);
 col+=uSunCol*(pow(max(sd,0.),700.)*4.+pow(max(sd,0.),10.)*.3+pow(max(sd,0.),2.)*.12*(1.-clamp(y*2.,0.,1.)));
 float md=dot(d,uMoonDir);col+=vec3(.85,.9,1.)*smoothstep(.9991,.9995,md)*uStars+vec3(.4,.5,.9)*pow(max(md,0.),80.)*.15*uStars;
 vec3 q=floor(d*170.);float s=h3(q);float star=step(.9968,s)*(.4+.6*sin(uTime*(1.+h3(q.zxy)*3.)+s*40.));
 col+=vec3(.85,.9,1.)*star*uStars*smoothstep(0.,.15,y);
 if(y>.05&&uStars>.4){float a=sin(d.x*5.+fb1(d.z*3.+uTime*.1)*6.+uTime*.3)*.5+.5;float band=exp(-pow((y-.4-.1*sin(d.x*3.+uTime*.2))*5.,2.));
  col+=mix(vec3(.1,1.,.5),vec3(.6,.2,1.),a)*band*.3*uStars*fb1(d.x*4.+uTime*.15);}
 if(y>.01){vec2 p=d.xz/(y+.18)*1.3+vec2(uTime*.012,uTime*.006);float c=smoothstep(.48,.78,fb2(p))*smoothstep(.01,.2,y);
  vec3 cc=mix(uZen*.5+uHor*.5,uSunCol*.8+.25,pow(max(sd,0.),3.)*.6)+uSunCol*.12;col=mix(col,cc*(.4+.6*day+.15),c*.85);}
 float az=atan(d.x,d.z);
 for(int L=0;L<3;L++){float fl=float(L);float f=fb1(az*(2.2+fl*1.4)+fl*13.7);
  float ridge=(.03+.17*f)*(1.-fl*.25)*(1.-uCity*.55)+.01;
  if(y<ridge&&y>-.2){float lit=clamp(.6+(n1(az*30.+fl*5.)-.5)*.3-(ridge-y)*1.5,.2,1.);
   vec3 mc=uMtn*(.4+.6*lit)*(.5+.5*day);float cap=smoothstep(.09,.14,y/(1.-fl*.2))*(1.-uCity);
   mc=mix(mc,vec3(.95,.97,1.)*(.35+.65*lit)*(day*.8+.2),cap);col=mix(mc,uHor*.9,(1.-fl*.33)*.5+.1);}}
 if(uCity>.01&&y>-.02&&y<.3){float cell=floor(az*60.);float mask=smoothstep(.3,.6,fb1(az*1.3+4.));
  float bh=(.015+h1(cell)*.1*pow(h1(cell+9.),1.3)+.02*uCity)*mask;
  if(y<bh&&mask>.05){vec3 bc=uMtn*.3;float wy=floor(y*130.),wx=floor(fract(az*60.)*5.);
   if(h3(vec3(cell,wy,wx))>.78)bc+=vec3(1.,.75,.35)*.6*smoothstep(.1,.6,uStars+.1);col=bc;}
  if(abs(y-bh)<.002&&h1(cell+2.)>.8&&mask>.3)col+=vec3(1.,.1,.1)*(.5+.5*sin(uTime*3.+cell))*uStars;}
 if(y<0.)col=mix(col,uFog,smoothstep(0.,-.03,y));
 gl_FragColor=vec4(col,1.);}`;
const VS_GROUND='precision highp float;attribute vec3 aPos;uniform mat4 uVP;varying float vR;void main(){vR=length(aPos.xz);gl_Position=uVP*vec4(aPos,1.);}';
const FS_GROUND=GLSL_P+'varying float vR;uniform vec3 uG,uFog;void main(){gl_FragColor=vec4(mix(uG,uFog,smoothstep(14.,150.,vR)),1.);}';
const VS_FLOOR='precision highp float;attribute vec3 aPos;uniform mat4 uVP;uniform float uTime;uniform vec3 uC;varying float vB;varying float vA;'+
 'void main(){float dist=length(aPos.xz);float dp=length(aPos.xz-uC.xz);float ring=pow(max(sin(dist*1.6-uTime*1.9),0.),6.)*exp(-dist*.14)*.9;'+
 'vB=.16+ring+exp(-dp*.9)*.55;vA=exp(-dist*.07);gl_Position=uVP*vec4(aPos,1.);}';
const FS_FLOOR='precision mediump float;varying float vB;varying float vA;uniform vec3 uT;void main(){gl_FragColor=vec4(uT*vB,vA);}';
const VS_WORLD='precision highp float;attribute vec3 aPos;attribute vec3 aCol;attribute vec2 aK;uniform mat4 uVP;uniform vec3 uCam,uAmb;uniform float uTime,uNight,uPt;varying vec4 vC;'+
 'void main(){vec3 p=aPos;float k=aK.x,r=aK.y;vec3 c=aCol*uAmb;float a=1.;'+
 'if(k>.5&&k<1.5||k>4.5){p.x+=sin(uTime*1.3+r*40.+p.z*.3)*.06*(p.y*.35+.2);p.z+=cos(uTime*1.1+r*30.)*.05*(p.y*.3+.2);}'+
 'if(k>2.5&&k<3.5){c=aCol*(.5+1.6*uNight+.25*sin(uTime*2.+r*30.));}'+
 'if(k>3.5&&k<4.5){p+=vec3(sin(uTime*.7+r*60.),sin(uTime*.9+r*20.)*.5,cos(uTime*.6+r*45.))*1.1;c=vec3(1.4,1.2,.3);a=uNight*(.5+.5*sin(uTime*3.+r*50.));}'+
 'gl_Position=uVP*vec4(p,1.);float d=max(length(p-uCam),.5);gl_PointSize=clamp(uPt*(k>4.5?.9:1.7)*5./d,1.2,9.);vC=vec4(c,a*clamp(1.4-d/110.,.1,1.));}';
const FS_PT='precision mediump float;varying vec4 vC;void main(){vec2 c=gl_PointCoord*2.-1.;float r2=dot(c,c);if(r2>1.)discard;gl_FragColor=vec4(vC.rgb*(1.+.2*(1.-r2)),vC.a);}';
const VS_CLOUD=`precision highp float;attribute vec3 aPos;attribute vec3 aCol;attribute vec4 aSkin;attribute vec3 aEx;
uniform mat4 uBones[${NB}];uniform float uHot[${NB}];uniform mat4 uVP;uniform vec3 uCam,uRoot,uTint,uMul,uHotCol;
uniform float uTime,uShim,uJit,uRise,uS,uW,uPulse,uBurst,uDis,uGun,uPt,uOrb,uAlpha;varying vec4 vC;
void main(){float kind=aEx.z,r=aEx.x;
 if(kind>.5&&kind<1.5&&uGun<.5){gl_Position=vec4(2.,2.,2.,1.);gl_PointSize=0.;vC=vec4(0.);return;}
 vec3 lp=aPos;
 if(kind>1.5&&kind<2.5){float an=uTime*uOrb;float cs=cos(an),sn=sin(an);lp=vec3(aPos.x*cs-aPos.z*sn,aPos.y,aPos.x*sn+aPos.z*cs);}
 else if(kind<.5||kind>2.5)lp.xz*=uW;
 int i0=int(aSkin.x+.5),i1=int(aSkin.z+.5);
 vec3 wp=(uBones[i0]*vec4(lp,1.)).xyz*aSkin.y+(uBones[i1]*vec4(lp,1.)).xyz*aSkin.w;
 wp=uRoot+(wp-uRoot)*uS;float h=uHot[i0];
 vec3 rv=vec3(sin(r*91.3),cos(r*57.1),sin(r*33.7+1.));float fade=1.;
 if(kind>2.5){float f=fract(uTime*(.22+.3*uRise)+r*7.);wp.y+=f*1.5*uS*(.3+uRise);wp.xz+=rv.xz*.14*f;fade=smoothstep(0.,.12,f)*(1.-f)*(.35+.65*uRise);}
 wp+=(uShim+uJit*.035*step(.72,fract(r*13.+uTime*9.)))*vec3(sin(uTime*2.2+r*47.),sin(uTime*1.7+r*61.),cos(uTime*2.6+r*34.));
 wp+=rv*.045*h;
 vec3 cd=wp-(uRoot+vec3(0.,1.1*uS,0.));float cl=length(cd)+1e-3;wp+=(cd/cl*.9+rv*.6)*uBurst*(.4+r)*1.7;
 float dt=clamp(uDis*1.4-r*.4,0.,1.);wp+=vec3(rv.x*.8,.5+abs(rv.y)*1.8,rv.z*.8)*dt*dt*2.;
 gl_Position=uVP*vec4(wp,1.);float d=max(length(wp-uCam),.35);float edge=aEx.y;
 gl_PointSize=clamp(uPt*(edge>.5?2.:1.2)*5./d*(1.+h*1.3+uPulse*.5+uBurst*1.2),1.4,13.);
 vec3 col=aCol*uMul+uTint;col=mix(col,uHotCol,clamp(h,0.,1.)*.85);col+=uHotCol*uPulse*.45*(.4+edge);col*=1.+uBurst*.6;
 vC=vec4(col,(1.-dt)*uAlpha*fade*clamp(1.3-d/60.,.1,1.));}`;
const VS_FXC='precision highp float;attribute vec4 aA;uniform mat4 uVP;uniform vec3 uCam,uPos,uDir,uC1,uC2;uniform float uMode,uR,uH,uT,uA,uPt,uTime;varying vec4 vC;'+
 'void main(){float th=aA.x,u=aA.y,v=aA.z,w=aA.w;vec3 p=uPos;float al=1.;'+
 'if(uMode<.5){float r=uR+(u-.5)*.9;float hh=v*v*uH*(1.-uT);p+=vec3(cos(th)*r,.06+hh,sin(th)*r);al=1.-uT*.6;}'+
 'else if(uMode<1.5){float hg=v*uH;float rad=uR*(.25+.75*u)*(1.-.55*v);float a=th+hg*2.2+uTime*4.*(.5+w);p+=vec3(cos(a)*rad,hg,sin(a)*rad);al=1.-v*.5;}'+
 'else if(uMode<2.5){float cz=1.-2.*u;float sr=sqrt(1.-cz*cz);float r=uR*(.92+.12*v);p+=vec3(cos(th)*sr*r,cz*r*.8+uH,sin(th)*sr*r);al=(1.-uT)*.9;}'+
 'else if(uMode<3.5){float f=fract(v+uTime*.7+w*.3);float rad=uR*(1.-f);float a=th+f*5.;p+=vec3(cos(a)*rad,(u-.5)*.5*(1.-f)+uH,sin(a)*rad);al=smoothstep(0.,.2,f);}'+
 'else{float rr=uR*pow(u,.33);float cz=1.-2.*v;float sr=sqrt(1.-cz*cz);vec3 o=vec3(cos(th)*sr,cz,sin(th)*sr)*rr;float tail=w*w*uR*5.*uH;'+
 'vec3 dir=normalize(uDir+vec3(0.,1e-4,0.));vec3 rt=normalize(cross(dir,vec3(0.,1.,0.)));vec3 up=cross(rt,dir);float ang=uTime*6.+tail*3.;'+
 'p+=o*(1.-w*.5)-dir*tail+(rt*cos(ang)+up*sin(ang))*sin(w*20.+uTime*8.)*.12*uR*w;al=1.-w*.7;}'+
 'float d=max(length(p-uCam),.5);gl_Position=uVP*vec4(p,1.);gl_PointSize=clamp(uPt*(uMode>3.5?1.7:1.9)*5./d,1.5,10.)*(.6+.4*al);'+
 'vC=vec4(mix(uC1,uC2,fract(v*3.+u*2.))*1.15,uA*al*clamp(14./d,.3,1.));}';
const VS_PTS='precision highp float;attribute vec3 aP;attribute vec4 aC;attribute float aS;uniform mat4 uVP;uniform vec3 uCam;uniform float uPt;varying vec4 vC;'+
 'void main(){gl_Position=uVP*vec4(aP,1.);float d=max(length(aP-uCam),.4);gl_PointSize=clamp(aS*uPt*5./d,1.5,16.);vC=aC;}';
