const FS_LINE='precision mediump float;uniform vec3 uCol;uniform float uA;void main(){gl_FragColor=vec4(uCol,uA);}';

let gl=null,prog={},VW=1280,VH=800,DPRV=1;
function compile(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);
 if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){const l=gl.getShaderInfoLog(s);console.error(l);throw new Error('shader: '+l);}return s;}
function mkProg(vs,fs,attribs,uniforms){const p=gl.createProgram();gl.attachShader(p,compile(gl.VERTEX_SHADER,vs));gl.attachShader(p,compile(gl.FRAGMENT_SHADER,fs));
 gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error('link: '+gl.getProgramInfoLog(p));
 const o={p:p,a:{},u:{}};for(const a of attribs)o.a[a]=gl.getAttribLocation(p,a);for(const u of uniforms)o.u[u]=gl.getUniformLocation(p,u);return o;}
function bindA(loc,vb,size,stride,off){gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,stride||0,off||0);gl.enableVertexAttribArray(loc);}
const _P=new Float32Array(16),_V=new Float32Array(16),_VP=new Float32Array(16);
let skyVbo,floorVbo,floorCount=0,groundVbo,groundCount=0,worldVbo=[],worldCount=0,fxcVbo,fxcCount=8000,ptsVbo;
const PTS_MAX=4000,ptsArr=new Float32Array(PTS_MAX*8);

function initGL(){
 const cv=$('gl-canvas');
 gl=cv.getContext('webgl',{antialias:false,alpha:false,depth:true,powerPreference:'high-performance'})||cv.getContext('experimental-webgl',{antialias:false,alpha:false,depth:true});
 if(!gl)throw new Error('WebGL unavailable');
 const cu=['uBones[0]','uHot[0]','uVP','uCam','uRoot','uTint','uMul','uHotCol','uTime','uShim','uJit','uRise','uS','uW','uPulse','uBurst','uDis','uGun','uPt','uOrb','uAlpha'];
 prog.sky=mkProg(VS_SKY,FS_SKY,['aPos'],['uR','uU','uF','uTy','uAsp','uTime','uStars','uCity','uZen','uHor','uSunCol','uSunDir','uMoonDir','uFog','uMtn']);
 prog.ground=mkProg(VS_GROUND,FS_GROUND,['aPos'],['uVP','uG','uFog']);
 prog.floor=mkProg(VS_FLOOR,FS_FLOOR,['aPos'],['uVP','uTime','uC','uT']);
 prog.world=mkProg(VS_WORLD,FS_PT,['aPos','aCol','aK'],['uVP','uCam','uAmb','uTime','uNight','uPt']);
 prog.cloud=mkProg(VS_CLOUD,FS_PT,['aPos','aCol','aSkin','aEx'],cu);
 prog.fxc=mkProg(VS_FXC,FS_PT,['aA'],['uVP','uCam','uPos','uDir','uC1','uC2','uMode','uR','uH','uT','uA','uPt','uTime']);
 prog.pts=mkProg(VS_PTS,FS_PT,['aP','aC','aS'],['uVP','uCam','uPt']);
 prog.line=mkProg(VS_LINE,FS_LINE,['aPos'],['uVP','uCol','uA']);
 skyVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,skyVbo);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
 // FXC buffer
 const a=new Float32Array(fxcCount*4);for(let i=0;i<fxcCount;i++){a[i*4]=Math.random()*6.2832;a[i*4+1]=Math.random();a[i*4+2]=Math.random();a[i*4+3]=Math.random();}
 fxcVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,fxcVbo);gl.bufferData(gl.ARRAY_BUFFER,a,gl.STATIC_DRAW);
 ptsVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,ptsVbo);gl.bufferData(gl.ARRAY_BUFFER,ptsArr,gl.DYNAMIC_DRAW);
 // hex floor lines + ground disc
 const R=.55,rr=16.5,arr=[],hexR=Math.sqrt(3)*R,hexH=1.5*R;
 for(let q=-30;q<=30;q++)for(let r=-30;r<=30;r++){const x=hexR*(q+r*.5),z=hexH*r;if(x*x+z*z>rr*rr)continue;
  for(let i=0;i<6;i++){const a1=Math.PI/3*i,a2=a1+Math.PI/3;arr.push(x+R*Math.cos(a1),.01,z+R*Math.sin(a1),x+R*Math.cos(a2),.01,z+R*Math.sin(a2));}}
 const fa=new Float32Array(arr);floorCount=fa.length/3;floorVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,floorVbo);gl.bufferData(gl.ARRAY_BUFFER,fa,gl.STATIC_DRAW);
 const g=[];const rings=[0,14,40,150];for(let j=0;j<3;j++)for(let i=0;i<48;i++){const a1=i/48*6.2832,a2=(i+1)/48*6.2832,r0=rings[j],r1=rings[j+1];
  g.push(Math.cos(a1)*r0,0,Math.sin(a1)*r0,Math.cos(a1)*r1,0,Math.sin(a1)*r1,Math.cos(a2)*r1,0,Math.sin(a2)*r1,Math.cos(a1)*r0,0,Math.sin(a1)*r0,Math.cos(a2)*r1,0,Math.sin(a2)*r1,Math.cos(a2)*r0,0,Math.sin(a2)*r0);}
 groundVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,groundVbo);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(g),gl.STATIC_DRAW);groundCount=g.length/3;
 buildWorld();
}
// organic world: trees, rocks, crystals, grass, fireflies as particle clouds
function buildWorld(){
 const P=[],Cc=[],K=[];
 const push=(x,y,z,c,k,m)=>{P.push(x,y,z);const j=.8+Math.random()*.4;Cc.push(c[0]*j,c[1]*j,c[2]*j);K.push(k,Math.random());};
 const sph=(cx,cy,cz,r,n,c,k,sy)=>{for(let i=0;i<n;i++){let x,y,z,l;do{x=rnd(-1,1);y=rnd(-1,1);z=rnd(-1,1);l=x*x+y*y+z*z;}while(l>1||l<1e-3);l=Math.sqrt(l);push(cx+x/l*r,cy+y/l*r*(sy||1),cz+z/l*r,c,k);}};
 for(let i=0;i<64;i++){const a=Math.random()*6.2832,rad=19+Math.random()*30,x=Math.cos(a)*rad,z=Math.sin(a)*rad,h=2.2+Math.random()*3.5,s=.7+Math.random()*.8;
  const kind=Math.random();
  for(let j=0;j<140;j++){const t=Math.random(),th=Math.random()*6.2832,rr=.16*s*(1-t*.5);push(x+Math.cos(th)*rr,t*h,z+Math.sin(th)*rr,[.32,.2,.1],0);}
  const cc=kind<.2?[.85,.4,.1]:(kind<.35?[.9,.7,.15]:[.15+Math.random()*.15,.5+Math.random()*.25,.14]);
  for(let b=0;b<3;b++)sph(x+rnd(-.9,.9)*s,h+rnd(-.2,.9)*s,z+rnd(-.9,.9)*s,(1.1+Math.random()*1.1)*s,330,cc,1,.8);}
 for(let i=0;i<46;i++){const a=Math.random()*6.2832,rad=17+Math.random()*38,r=.5+Math.random()*1.7;sph(Math.cos(a)*rad,r*.4,Math.sin(a)*rad,r,260,[.34,.34,.37],2,.7);}
 for(let i=0;i<26;i++){const a=Math.random()*6.2832,rad=16+Math.random()*30,x=Math.cos(a)*rad,z=Math.sin(a)*rad,col=[[.2,1.,1.2],[1.2,.3,1.],[1.2,.9,.2]][i%3];
  for(let c=0;c<4;c++){const h=.8+Math.random()*2.4,ox=rnd(-.5,.5),oz=rnd(-.5,.5),tx=rnd(-.5,.5),tz=rnd(-.5,.5);
   for(let j=0;j<70;j++){const t=Math.random(),th=Math.random()*6.2832,rr=.16*(1-t);push(x+ox+tx*t+Math.cos(th)*rr,t*h,z+oz+tz*t+Math.sin(th)*rr,col,3);}}}
 for(let i=0;i<9000;i++){const a=Math.random()*6.2832,rad=12+Math.random()*34;push(Math.cos(a)*rad,Math.random()*.55,Math.sin(a)*rad,[.2+Math.random()*.2,.55+Math.random()*.2,.15],5);}
 for(let i=0;i<500;i++){const a=Math.random()*6.2832,rad=4+Math.random()*30;push(Math.cos(a)*rad,.6+Math.random()*2.5,Math.sin(a)*rad,[1.4,1.2,.3],4);}
 for(let i=0;i<90;i++){const a=Math.random()*6.2832,rad=70+Math.random()*850,x=Math.cos(a)*rad,z=Math.sin(a)*rad,h=3+Math.random()*6,s=.8+Math.random()*1.2;for(let j=0;j<50;j++){const t=Math.random(),th=Math.random()*6.2832,rr=.2*s*(1-t*.5);push(x+Math.cos(th)*rr,t*h,z+Math.sin(th)*rr,[.32,.2,.1],0);}sph(x,h,z,(1.3+Math.random())*s,170,[[.85,.4,.1],[.15,.6,.2],[.3,.5,.9],[.7,.3,.8]][i%4],1,.8);} // far-world landmarks
 for(let i=0;i<70;i++){const a=Math.random()*6.2832,rad=60+Math.random()*880,r=.8+Math.random()*2;sph(Math.cos(a)*rad,r*.4,Math.sin(a)*rad,r,120,[.34,.34,.37],2,.7);}
 worldCount=P.length/3;
 const mk=(arr)=>{const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(arr),gl.STATIC_DRAW);return b;};
 worldVbo=[mk(P),mk(Cc),mk(K)];
}
// ---- time of day ----
const TOD_KF=[
 [0,[.01,.015,.05],[.03,.04,.1],[0,0,0],1,[.03,.04,.07],[.02,.03,.06],[.28,.33,.55]],
 [5.5,[.2,.25,.5],[1,.5,.4],[1.3,.6,.3],.25,[.25,.2,.3],[.5,.35,.35],[.7,.6,.7]],
 [8,[.25,.5,.9],[.7,.8,1],[1.4,1.2,.9],0,[.25,.35,.5],[.6,.7,.85],[1,1,1]],
 [12,[.15,.4,.95],[.6,.8,1],[1.5,1.4,1.2],0,[.3,.4,.5],[.6,.75,.9],[1.1,1.1,1.05]],
 [17,[.25,.45,.85],[.9,.75,.6],[1.5,1.1,.7],0,[.25,.3,.4],[.7,.65,.6],[1,.95,.9]],
 [19,[.12,.12,.35],[1.2,.4,.2],[1.4,.4,.15],.2,[.15,.1,.18],[.5,.3,.25],[.8,.55,.5]],
 [21,[.02,.03,.1],[.15,.1,.25],[0,0,0],.9,[.05,.05,.1],[.08,.07,.15],[.3,.35,.6]],
 [24,[.01,.015,.05],[.03,.04,.1],[0,0,0],1,[.03,.04,.07],[.02,.03,.06],[.28,.33,.55]]];
const TOD={hour:12,auto:false,zen:[0,0,0],hor:[0,0,0],sun:[0,0,0],stars:0,mtn:[0,0,0],fog:[0,0,0],amb:[1,1,1],sunDir:[0,1,0],moonDir:[0,-1,0],night:0,floor:[0,1,.8],ground:[.05,.08,.07]};
function lerpV(a,b,t){return a.map((v,i)=>v+(b[i]-v)*t);}
function updateTOD(){
 const h=((TOD.hour%24)+24)%24;let i=0;while(i<TOD_KF.length-2&&h>=TOD_KF[i+1][0])i++;
 const A=TOD_KF[i],B=TOD_KF[i+1],t=(h-A[0])/(B[0]-A[0]);
 TOD.zen=lerpV(A[1],B[1],t);TOD.hor=lerpV(A[2],B[2],t);TOD.sun=lerpV(A[3],B[3],t);TOD.stars=A[4]+(B[4]-A[4])*t;TOD.mtn=lerpV(A[5],B[5],t);TOD.fog=lerpV(A[6],B[6],t);TOD.amb=lerpV(A[7],B[7],t);
 const ang=(h-6)/12*Math.PI,el=Math.sin(ang),az=.9;
 TOD.sunDir=V3.norm([Math.cos(az)*Math.cos(ang),el,Math.sin(az)*Math.cos(ang)]);TOD.moonDir=V3.scale(TOD.sunDir,-1);
 TOD.sun=V3.scale(TOD.sun,smooth((el+.05)/.15));TOD.night=clamp(TOD.stars,0,1);
 TOD.floor=lerpV([.0,1,.8],[.6,.2,1],TOD.night*.8);TOD.ground=V3.scale(TOD.fog,.35);
}
