const CAM={eye:[0,1.6,-5],target:[0,1.2,0],ang:0,fov:50,yaw:0,pitch:.2,dist:6,view:0,sm:null,shake:0};
const VIEWS=['CLASSIC SIDE','WIDE ARENA','OVER SHOULDER','LOW CINEMATIC','TOP DOWN','FREE ORBIT'];
// ---- CPU particle FX ----
const FXP=[];
function emit(p,v,c,life,size,drag,grav){if(FXP.length>=PTS_MAX)FXP.shift();FXP.push({p:[p[0],p[1],p[2]],v:v,c:c,life:life,max:life,s:size||2,drag:drag===undefined?2:drag,g:grav||0});}
function burst(p,n,spd,c1,c2,life,size,grav){for(let i=0;i<n;i++){const d=V3.norm([Math.random()-.5,Math.random()-.5,Math.random()-.5]),m=Math.random(),sp=spd*(.3+Math.random()*.7);
 emit(p,V3.scale(d,sp),[c1[0]+(c2[0]-c1[0])*m,c1[1]+(c2[1]-c1[1])*m,c1[2]+(c2[2]-c1[2])*m],life*(.5+Math.random()*.5),size,2,grav);}}
function stepFX(dt){for(let i=FXP.length-1;i>=0;i--){const f=FXP[i];f.life-=dt;if(f.life<=0){FXP.splice(i,1);continue;}
 f.v[1]-=f.g*dt;const k=Math.max(0,1-f.drag*dt);f.v[0]*=k;f.v[1]*=k;f.v[2]*=k;f.p[0]+=f.v[0]*dt;f.p[1]+=f.v[1]*dt;f.p[2]+=f.v[2]*dt;if(f.p[1]<.02){f.p[1]=.02;f.v[1]*=-.3;}}}
function drawFXP(VP){const n=Math.min(FXP.length,PTS_MAX);if(!n)return;
 for(let i=0;i<n;i++){const f=FXP[i],a=f.life/f.max,o=i*8;ptsArr[o]=f.p[0];ptsArr[o+1]=f.p[1];ptsArr[o+2]=f.p[2];ptsArr[o+3]=f.c[0];ptsArr[o+4]=f.c[1];ptsArr[o+5]=f.c[2];ptsArr[o+6]=a;ptsArr[o+7]=f.s*(.5+.5*a);}
 const P=prog.pts;gl.useProgram(P.p);gl.uniformMatrix4fv(P.u.uVP,false,VP);gl.uniform3fv(P.u.uCam,CAM.eye);gl.uniform1f(P.u.uPt,DPRV);
 gl.bindBuffer(gl.ARRAY_BUFFER,ptsVbo);gl.bufferSubData(gl.ARRAY_BUFFER,0,ptsArr.subarray(0,n*8));
 bindA(P.a.aP,ptsVbo,3,32,0);bindA(P.a.aC,ptsVbo,4,32,12);bindA(P.a.aS,ptsVbo,1,32,28);gl.drawArrays(gl.POINTS,0,n);
 gl.disableVertexAttribArray(P.a.aP);gl.disableVertexAttribArray(P.a.aC);gl.disableVertexAttribArray(P.a.aS);}
function drawFXC(VP,e,count){const P=prog.fxc;
 gl.uniform3fv(P.u.uPos,e.pos);gl.uniform3fv(P.u.uDir,e.dir||[0,0,1]);gl.uniform3fv(P.u.uC1,e.c1);gl.uniform3fv(P.u.uC2,e.c2);
 gl.uniform1f(P.u.uMode,e.mode);gl.uniform1f(P.u.uR,e.r);gl.uniform1f(P.u.uH,e.h||0);gl.uniform1f(P.u.uT,e.t||0);gl.uniform1f(P.u.uA,e.a===undefined?1:e.a);
 gl.drawArrays(gl.POINTS,0,Math.min(fxcCount,count||e.n||fxcCount));}

