function makeFighter(w,name,key,slot){
 const e=w.create(name);
 e.add(new C('Transform',{pos:[0,0,0],yaw:0}));
 e.add(new C('Rig',{mats:new Float32Array(NB*16),pos:new Float32Array(NB*3)}));
 e.add(new C('Fighter',{slot:slot,key:key,A:ARCH[key],S:ARCH[key].S,hp:100,max:100,en:30,state:'free',st:0,mv:null,mdef:null,hitDone:false,spawned:false,
  vx:0,vz:0,y:0,vy:0,air:false,block:false,stun:0,freeze:0,slow:0,combo:0,comboT:0,chainIdx:0,chainT:0,queue:null,buf:{punch:0,kick:0,p1:0,p2:0,jump:0},
  pulse:0,burst:0,dis:0,flash:0,hot:new Float32Array(NB),hotT:new Float32Array(NB),in:mkInput(),ai:{t:0,mode:'idle',lvl:.5,mt:0},ctl:'ai',lastHit:-9,fall:0,inv:0,sword:0,dpCd:0,dpReq:null,dpReqT:0,tick:0,dpApex:false,dpLand:null,slashDone:false,swTip:null}));
 e.add(new C('Animator',{t:0,blendFrom:null,blendT:1,prev:'',last:null,pose:null}));
 e.add(new C('Cloud'));
 return e;}
function setArch(e,key){const F=e.get('Fighter');F.key=key;F.A=ARCH[key];F.S=F.A.S;F.max=F.A.hp;F.hp=F.max;if(M.mode==='TPS'&&F.slot===0){F.max=OW.START_HP;F.hp=OW.START_HP;}ensureCloud(key);}
const HOT={p1:['rHand','rFore'],p2:['lHand','lFore'],p3:['rHand','rFore','rArm'],k1:['rFoot','rShin','rThigh']};
function startAtk(f,id){f.state='atk';f.st=0;f.mv=id;f.hitDone=false;f.spawned=false;f.queue=null;f.slashDone=false;f.tick=0;f.dpApex=false;f.dpLand=null;
 if(id==='pw1'||id==='pw2'){const pid=f.A.pw[id==='pw1'?0:1],p=PW[pid];f.en-=p.cost;f.mdef={pw:pid,st:p.fx,en:p.fx+(p.hold||.18),dur:p.dur,anim:p.anim};}
 else f.mdef=MV[id];}
function dist2(a,b){return Math.hypot(a.pos[0]-b.pos[0],a.pos[2]-b.pos[2]);}
function faceDir(T){return [Math.sin(T.yaw),Math.cos(T.yaw)];}
function inRange(fT,f,oT,o,reach){
 const d=dist2(fT,oT),dx=oT.pos[0]-fT.pos[0],dz=oT.pos[2]-fT.pos[2],fd=faceDir(fT);
 if(d>reach*f.S+.3*o.S)return false;
 const cs=(dx*fd[0]+dz*fd[1])/(d||1);if(cs<.45)return false;
 if(o.y>1.0&&f.y<.3)return false;return true;}
function dmgFx(p,att,heavy){const h=att.A.hot;burst(p,heavy?40:18,heavy?9:6,[1.5,1.4,1.2],h,heavy?.45:.3,3,6);}
function applyHit(aT,a,dT,d,o){
 // o: {dmg,kb,stun,launch,freeze,slow,pw,heavy,dir}
 if(d.inv>0||d.state==='ko'||d.state==='down'||M.state!=='fight')return false;
 let dmg=o.dmg,kb=o.kb,stun=o.stun;
 const hp=[dT.pos[0],dT.pos[1]+(1.1*d.S)+d.y,dT.pos[2]];
 let dx=dT.pos[0]-aT.pos[0],dz=dT.pos[2]-aT.pos[2];const l=Math.hypot(dx,dz)||1;dx/=l;dz/=l;
 const blocked=d.block&&d.state==='free'&&!d.air&&!o.launch;
 if(blocked){dmg*=.12;kb*=.35;stun=.14;burst(hp,16,5,[.3,.8,1.6],[.6,1.2,2],.3,3,0);d.en=Math.min(100,d.en+2);}
 else{dmgFx(hp,a,o.heavy);d.flash=1;d.burst=Math.max(d.burst,o.heavy?.6:.25);
  d.en=Math.min(100,d.en+4);a.en=Math.min(100,a.en+(o.pw?3:6));a.combo++;a.comboT=1.4;
  if(o.freeze){d.freeze=o.freeze;}if(o.slow)d.slow=o.slow;
  if(o.launch){d.vy=o.launch;d.air=true;stun=2;}
  d.state='hit';d.st=0;d.stun=o.freeze?Math.max(stun,o.freeze):stun;d.mv=null;d.queue=null;}
 d.hp=Math.max(0,d.hp-dmg);d.vx=dx*kb;d.vz=dz*kb;
 HITSTOP=Math.max(HITSTOP,blocked?.03:.04+dmg*.004);CAM.shake=Math.max(CAM.shake,blocked?.04:.08+dmg*.006);
 if(d.hp<=0&&M.state==='fight'){d.state='ko';d.st=0;d.vx=dx*4;d.vz=dz*4;d.vy=4;d.air=true;a.state==='atk'&&(a.state='free');a.hit0=0;endRound(a,d);}
 return !blocked;}
function sink(e){return {T:e.get('Transform'),F:e.get('Fighter')};}
// ----- power implementations -----
function chestPos(T,F,fwd){const f=faceDir(T);return [T.pos[0]+f[0]*(fwd||.5)*F.S,T.pos[1]+(1.25*F.S)+F.y,T.pos[2]+f[1]*(fwd||.5)*F.S];}
function aimDir(T,oT,o,F){const c=chestPos(T,F,.5),tg=[oT.pos[0],oT.pos[1]+1.1*o.S+o.y*.6,oT.pos[2]];return V3.norm(V3.sub(tg,c));}
function spawnProj(a,aT,o,oT,p){const c=chestPos(aT,a,p.fwd||.6);if(p.up)c[1]+=p.up;
 const d=p.dir||aimDir(aT,oT,o,a);PROJ.push(Object.assign({own:a,tgt:o,tT:oT,aT:aT,pos:c,vel:V3.scale(d,p.spd),life:p.life||2.2,t:0,home:0,grav:0,stun:.26,kb:3,launch:0,freeze:0,slow:0,n:4000,tail:1},p));}
function castPower(e,oe,pid){
 const a=e.get('Fighter'),aT=e.get('Transform'),o=oe.get('Fighter'),oT=oe.get('Transform');
 a.burst=Math.max(a.burst,.4);
 const A=a.A;
 switch(pid){
 case 'plasma':spawnProj(a,aT,o,oT,{spd:13,r:.34,dmg:12,c1:[.2,1,1.3],c2:[1.5,1,.2],kb:4,stun:.3,n:5000,heavy:1});break;
 case 'fire':spawnProj(a,aT,o,oT,{spd:8.5,r:.55,dmg:15,c1:[1.5,.35,.05],c2:[1.6,1.3,.3],kb:5,stun:.34,n:6000,tail:1.3,heavy:1});break;
 case 'shards':{const b=aimDir(aT,oT,o,a);for(let i=-1;i<=1;i++){const an=i*.2,c=Math.cos(an),s=Math.sin(an);
   spawnProj(a,aT,o,oT,{dir:V3.norm([b[0]*c-b[2]*s,b[1],b[0]*s+b[2]*c]),spd:16,r:.17,dmg:5,c1:[.5,1.2,1.7],c2:[1.5,1.7,1.9],kb:2,stun:.22,slow:1.6,n:1800,tail:1.5});}break;}
 case 'orb':spawnProj(a,aT,o,oT,{spd:4.6,r:.48,dmg:13,c1:[.8,.1,1.4],c2:[1.7,.6,1.9],kb:3,stun:.5,home:2.6,life:4,n:6000,heavy:1});break;
 case 'boulder':spawnProj(a,aT,o,oT,{spd:9.5,r:.62,dmg:17,c1:[.4,.35,.25],c2:[.5,1.2,.4],kb:6.5,stun:.45,grav:9,up:1.2,dir:V3.norm([aimDir(aT,oT,o,a)[0],.55,aimDir(aT,oT,o,a)[2]]),n:5000,tail:.5,heavy:1});break;
 case 'nova':GFX.push({type:'nova',a,aT,o,oT,t:0,dur:.7,done:false,pos:[aT.pos[0],aT.pos[1]+(.9*a.S),aT.pos[2]],r:0});burst(aT.pos,90,10,[1.2,1,.3],A.hot,.9,3.5,0);break;
 case 'pillar':GFX.push({type:'pillar',a,aT,o,oT,t:0,dur:1.3,done:false,pos:[oT.pos[0],0,oT.pos[2]]});break;
 case 'zero':GFX.push({type:'zero',a,aT,o,oT,t:0,dur:.9,done:false,pos:[aT.pos[0],0,aT.pos[2]]});break;
 case 'horizon':GFX.push({type:'horizon',a,aT,o,oT,t:0,dur:1.6,done:false,pos:[oT.pos[0],.9,oT.pos[2]]});break;
 case 'quake':GFX.push({type:'quake',a,aT,o,oT,t:0,dur:1.3,done:false,pos:[aT.pos[0],0,aT.pos[2]]});break;
 case 'bolt':{const c=chestPos(aT,a,.5),tg=[oT.pos[0],oT.pos[1]+1.2*o.S+o.y*.5,oT.pos[2]];bolt(c,tg);
   if(!(o.y>1.3))applyHit(aT,a,oT,o,{dmg:11*A.dmg,kb:2,stun:.35,pw:1});GFX.push({type:'flash',pos:tg,t:0,dur:.3});break;}
 case 'visor':GFX.push({type:'beam',e:e,a:a,aT:aT,o:o,oT:oT,t:0,dur:1.15,tick:.12,dir:null});break;
 case 'eclipse':GFX.push({type:'eclipse',a:a,aT:aT,o:o,oT:oT,t:0,dur:1.45,done:false,pos:[aT.pos[0],aT.pos[1]+1.0*a.S,aT.pos[2]]});break;
 case 'dash':{const dx=oT.pos[0]-aT.pos[0],dz=oT.pos[2]-aT.pos[2],l=Math.hypot(dx,dz)||1;const from=chestPos(aT,a,0);
   const np=[oT.pos[0]+dx/l*1.4,0,oT.pos[2]+dz/l*1.4];
   bolt(from,[np[0],from[1],np[2]]);aT.pos[0]=np[0];aT.pos[2]=np[2];aT.yaw=Math.atan2(-dx,-dz);
   burst(from,60,8,[1.7,1.6,.5],[.5,.9,2],.5,3,0);
   applyHit(aT,a,oT,o,{dmg:15*A.dmg,kb:4,stun:.4,pw:1,heavy:1});break;}
 }}
function bolt(a,b){const n=26;let prev=a;for(let i=1;i<=n;i++){const t=i/n,j=(1-Math.abs(t*2-1)*.2)*.45;
  const p=[a[0]+(b[0]-a[0])*t+rnd(-j,j),a[1]+(b[1]-a[1])*t+rnd(-j,j),a[2]+(b[2]-a[2])*t+rnd(-j,j)];
  for(let k=0;k<8;k++){const q=V3.lerp(prev,p,k/8);emit(q,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],[1.6+Math.random()*.2,1.6,.6+Math.random()],.22+Math.random()*.2,3.4,3,0);}prev=p;}}
function updateProj(dt){
 for(let i=PROJ.length-1;i>=0;i--){const p=PROJ[i];p.t+=dt;p.life-=dt;
  if(p.home){const tg=[p.tT.pos[0],p.tT.pos[1]+1.1*p.tgt.S,p.tT.pos[2]],d=V3.norm(V3.sub(tg,p.pos)),sp=V3.len(p.vel);const k=Math.min(1,p.home*dt);
   p.vel=V3.scale(V3.norm(V3.lerp(V3.norm(p.vel),d,k)),sp);}
  p.vel[1]-=p.grav*dt;p.pos[0]+=p.vel[0]*dt;p.pos[1]+=p.vel[1]*dt;p.pos[2]+=p.vel[2]*dt;
  emit(p.pos,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],V3.lerp(p.c1,p.c2,Math.random()),.35,2.4,3,0);
  const o=p.tgt,oT=p.tT;const dh=Math.hypot(p.pos[0]-oT.pos[0],p.pos[2]-oT.pos[2]);
  const hitB=dh<p.r+.45*o.S&&p.pos[1]>oT.pos[1]+o.y-.2&&p.pos[1]<o.y+1.9*o.S;
  if(hitB&&M.state==='fight'){applyHit(p.aT,p.own,oT,o,{dmg:p.dmg*p.own.A.dmg,kb:p.kb,stun:p.stun,launch:p.launch,freeze:p.freeze,slow:p.slow,pw:1,heavy:p.heavy});
   burst(p.pos,p.heavy?70:30,9,p.c1,p.c2,.6,3.5,2);GFX.push({type:'flash',pos:[p.pos[0],p.pos[1],p.pos[2]],t:0,dur:.35,c1:p.c1,c2:p.c2});PROJ.splice(i,1);continue;}
  if(p.life<=0||p.pos[1]<.05||Math.hypot(p.pos[0],p.pos[2])>40){burst(p.pos,20,5,p.c1,p.c2,.4,3,2);PROJ.splice(i,1);}}}
function updateGFX(dt){
 for(let i=GFX.length-1;i>=0;i--){const g=GFX[i];g.t+=dt;
  if(g.type==='nova'){g.r=g.t/.5*3.6;if(!g.done&&g.t>.05){g.done=true;
    if(dist2(g.aT,g.oT)<3.8*g.a.S+.3&&g.o.state!=='ko')applyHit(g.aT,g.a,g.oT,g.o,{dmg:22*g.a.A.dmg,kb:6,stun:.5,launch:6.2,pw:1,heavy:1});}}
  else if(g.type==='pillar'){if(!g.done&&g.t>.7){g.done=true;burst([g.pos[0],.3,g.pos[2]],80,9,[1.5,.5,.1],[1.6,1.4,.3],.8,3.5,-3);
    if(Math.hypot(g.oT.pos[0]-g.pos[0],g.oT.pos[2]-g.pos[2])<1.5&&g.o.y<1.3)applyHit(g.aT,g.a,g.oT,g.o,{dmg:22*g.a.A.dmg,kb:2,stun:.5,launch:7,pw:1,heavy:1});}}
  else if(g.type==='zero'){g.r=g.t/.6*4.4;if(!g.done&&g.r>dist2(g.aT,g.oT)-.3){g.done=true;
    if(g.o.state!=='ko'&&g.o.y<1.5)applyHit(g.aT,g.a,g.oT,g.o,{dmg:13*g.a.A.dmg,kb:3,stun:.6,freeze:1.3,pw:1,heavy:1});}}
  else if(g.type==='horizon'){const dx=g.pos[0]-g.oT.pos[0],dz=g.pos[2]-g.oT.pos[2],d=Math.hypot(dx,dz);
    if(g.t<1.05&&g.o.state!=='ko'&&d>.4&&d<5){const k=Math.min(1,dt*6)*Math.min(4,d);g.oT.pos[0]+=dx/d*k*dt*2.2;g.oT.pos[2]+=dz/d*k*dt*2.2;}
    if(!g.done&&g.t>1.1){g.done=true;burst(g.pos,110,11,[1.7,.5,1.9],[.5,.1,1],.9,3.5,0);
     if(d<2.4&&g.o.state!=='ko')applyHit(g.aT,g.a,g.oT,g.o,{dmg:19*g.a.A.dmg,kb:3,stun:.5,launch:5.5,pw:1,heavy:1});}}
  else if(g.type==='quake'){const R=g.t*7.5;g.r=R;if(!g.done&&Math.abs(R-dist2(g.aT,g.oT))<.7){if(g.o.y<.5&&g.o.state!=='ko'){g.done=true;
    applyHit(g.aT,g.a,g.oT,g.o,{dmg:21*g.a.A.dmg,kb:3,stun:.5,launch:4.8,pw:1,heavy:1});}}
   if(Math.random()<.9){const an=Math.random()*6.28;emit([g.pos[0]+Math.cos(an)*R,.1,g.pos[2]+Math.sin(an)*R],[rnd(-1,1),rnd(2,5),rnd(-1,1)],[.6,.55,.4],.6,3.2,1,9);}}
  updateGFXExt(g,dt);
  if(g.t>=g.dur)GFX.splice(i,1);}}
function drawGFX(VP){
 const P=prog.fxc;gl.useProgram(P.p);gl.uniformMatrix4fv(P.u.uVP,false,VP);gl.uniform3fv(P.u.uCam,CAM.eye);gl.uniform1f(P.u.uPt,DPRV);gl.uniform1f(P.u.uTime,world.t);
 bindA(P.a.aA,fxcVbo,4);
 for(const g of GFX){const k=g.t/g.dur;
  if(g.type==='nova'){const h=g.a.A.hot;drawFXC(VP,{mode:2,pos:g.pos,r:Math.max(.1,g.r),h:0,t:k,a:1,c1:[1.5,1.3,.4],c2:h,n:7000});
   drawFXC(VP,{mode:0,pos:[g.pos[0],0,g.pos[2]],r:Math.max(.1,g.r*1.05),h:.7,t:k,a:1,c1:h,c2:[1.5,1.3,.5],n:6000});}
  else if(g.type==='pillar'){if(g.t<.7)drawFXC(VP,{mode:0,pos:g.pos,r:1.5*(1-.2*Math.sin(g.t*18)),h:.2,t:0,a:.9,c1:[1.5,.3,.05],c2:[1.5,1,.2],n:2500});
   else drawFXC(VP,{mode:1,pos:g.pos,r:1.2,h:4.2,t:k,a:Math.min(1,(g.dur-g.t)*2.5),c1:[1.6,.4,.05],c2:[1.6,1.4,.3],n:8000});}
  else if(g.type==='zero'){drawFXC(VP,{mode:2,pos:[g.pos[0],.6,g.pos[2]],r:Math.max(.1,g.r),h:0,t:k,a:.8,c1:[.5,1.3,1.8],c2:[1.5,1.8,2],n:7000});
   drawFXC(VP,{mode:0,pos:g.pos,r:Math.max(.1,g.r),h:.9,t:k,a:1,c1:[.5,1.3,1.8],c2:[1.6,1.8,2],n:6000});}
  else if(g.type==='horizon'){const f=g.t<1.1?1:Math.max(0,1-(g.t-1.1)*2);drawFXC(VP,{mode:3,pos:g.pos,r:3.2*(g.t<1.1?1:1+(g.t-1.1)*3),h:0,t:k,a:f,c1:[.6,.1,1.2],c2:[1.8,.6,2],n:8000});}
  else if(g.type==='quake')drawFXC(VP,{mode:0,pos:g.pos,r:Math.max(.2,g.r),h:1.1,t:k,a:Math.max(0,1-k),c1:[.5,.45,.3],c2:[.6,1.5,.4],n:8000});
  else if(g.type==='flash')drawFXC(VP,{mode:2,pos:g.pos,r:.3+g.t*3.5,h:0,t:k,a:1,c1:g.c1||[1.6,1.6,1],c2:g.c2||[.6,.9,2],n:2500});
  else drawGFXExt(VP,g,k);}
 for(const p of PROJ){const sp=V3.len(p.vel)||1;drawFXC(VP,{mode:4,pos:p.pos,dir:V3.scale(p.vel,1/sp),r:p.r,h:p.tail,c1:p.c1,c2:p.c2,a:1,n:p.n});}
 gl.disableVertexAttribArray(P.a.aA);}
// ----- fighter update -----
function targetHot(F){F.hotT.fill(0);
 if(F.state==='atk'&&F.mdef){const m=F.mdef,id=F.mv;let h=0;if(F.st<m.st)h=.55*F.st/m.st;else if(F.st<m.en*1.5)h=1;else h=Math.max(0,1-(F.st-m.en*1.5)/.15);
  const bones=m.pw?(m.pw==='visor'?['head','neck','helmet']:['lHand','rHand','lFore','rFore']):HOT[id];for(const b of bones)F.hotT[BIDX[b]]=h;
  F.pulse+=((m.pw?(F.st<m.en+.1?1:0):.3*h)-F.pulse)*.2;}
 else F.pulse+=(0-F.pulse)*.12;}
function updateFighter(e,oe,dt,real){
 const T=e.get('Transform'),F=e.get('Fighter'),oT=oe.get('Transform'),O=oe.get('Fighter');
 for(const k in F.buf){if(F.in.press[k]){F.buf[k]=.16;F.in.press[k]=0;}if(F.buf[k]>0)F.buf[k]-=dt;}
 if(F.in.dp){F.dpReq=F.in.dp;F.dpReqT=.25;F.in.dp=null;}
 if(F.dpReqT>0){F.dpReqT-=dt;if(F.dpReqT<=0)F.dpReq=null;}
 F.inv=Math.max(0,F.inv-dt);F.dpCd=Math.max(0,F.dpCd-dt);
 if(F.sword>0&&M.state==='fight'){F.sword-=dt;if(F.sword<=0){F.sword=0;swordFade(e,F,T);}}
 F.comboT-=dt;if(F.comboT<=0)F.combo=0;F.chainT-=dt;F.flash=Math.max(0,F.flash-dt*5);F.burst=Math.max(0,F.burst-dt*2.6);
 if(F.freeze>0)F.freeze-=dt;if(F.slow>0)F.slow-=dt;
 F.en=Math.min(100,F.en+(real?2.2:0)*dt);
 F.st+=dt;
 const dx=oT.pos[0]-T.pos[0],dz=oT.pos[2]-T.pos[2],d=Math.hypot(dx,dz)||1;
 let yawT=Math.atan2(dx,dz);
 F.block=false;
 if(F.state==='free'){
  const sp=F.A.spd*2.7*(F.slow>0?.5:1);
  F.block=F.in.block&&!F.air;
  const spd=F.block?sp*.35:sp;
  const mx=F.in.mx,mz=F.in.mz,m=Math.min(1,Math.hypot(mx,mz));
  if(!F.air){const k=Math.min(1,dt*10);F.vx+=((m>.05?mx/(m>0?Math.hypot(mx,mz):1)*spd*m:0)-F.vx)*k;F.vz+=((m>.05?mz/Math.hypot(mx,mz)*spd*m:0)-F.vz)*k;}
  const _dp=(!F.air&&!F.block)?chordPick(F):null;
  if(_dp)startDP(F,_dp);
  else if(F.buf.jump>0&&F.buf.jump<=CHORD_AGE&&!F.air&&!F.block){F.vy=JUMPV*(.92+.08*F.A.spd);F.air=true;F.buf.jump=0;}
  if(!F.block&&F.state==='free'){
   if(F.buf.p1>0&&F.en>=PW[F.A.pw[0]].cost&&!F.air){F.buf.p1=0;startAtk(F,'pw1');}
   else if(F.buf.p2>0&&F.en>=PW[F.A.pw[1]].cost&&!F.air){F.buf.p2=0;startAtk(F,'pw2');}
   else if(F.buf.punch>0&&F.buf.punch<=CHORD_AGE){F.buf.punch=0;F.chainIdx=F.chainT>0?(F.chainIdx+1)%3:0;startAtk(F,'p'+(F.chainIdx+1));}
   else if(F.buf.kick>0&&F.buf.kick<=CHORD_AGE){F.buf.kick=0;startAtk(F,'k1');}}
 }else if(F.state==='atk'&&dpCancel(F)){
 }else if(F.state==='atk'){
  const m=F.mdef;
  if(F.air){}else{F.vx*=Math.max(0,1-dt*8);F.vz*=Math.max(0,1-dt*8);}
  if(!m.pw&&!m.dp&&F.st<m.en&&d>.85*F.S){const l=m.lunge*(1-F.st/m.en);F.vx=dx/d*l;F.vz=dz/d*l;}
  if(F.sword>0&&!m.pw&&!m.dp&&!F.slashDone&&F.st>=m.st){F.slashDone=true;slashFx(T,F,F.mv);}
  if(!m.pw&&!m.dp&&!F.hitDone&&F.st>=m.st&&F.st<=m.en&&inRange(T,F,oT,O,m.reach*(F.sword>0?1.4:1))){
   F.hitDone=true;applyHit(T,F,oT,O,{dmg:m.dmg*F.A.dmg*(F.sword>0?1.8:1),kb:m.kb*(F.sword>0?1.3:1),stun:m.stun,heavy:m.dmg>=8||F.sword>0});}
  if(m.pw&&!F.spawned&&F.st>=m.st){F.spawned=true;castPower(e,oe,m.pw);}
  if(m.dp)updateDP(e,oe,F,T,O,oT,dt,m);
  if(F.buf.punch>0&&F.st>m.st&&!m.pw&&!m.dp&&F.mv!=='k1')F.queue='punch';
  if(F.buf.kick>0&&F.st>m.en*.8&&!m.pw&&!m.dp)F.queue='kick';
  if(F.st>=m.dur||(F.queue&&F.st>m.en+.03&&!m.pw&&!m.dp)){
   const q=F.queue;F.state='free';F.chainT=.5;F.mv=null;
   if(q==='punch'){F.buf.punch=0;F.chainIdx=(F.chainIdx+1)%3;if(F.mdef.anim==='k1')F.chainIdx=0;startAtk(F,'p'+(F.chainIdx+1));}
   else if(q==='kick'){F.buf.kick=0;startAtk(F,'k1');}}
 }else if(F.state==='hit'){
  const k=Math.max(0,1-dt*5);if(!F.air){F.vx*=k;F.vz*=k;}
  if(F.air&&F.vy<=0&&F.y<=0){F.state='down';F.st=0;}
  else if(!F.air&&F.st>=F.stun&&F.freeze<=0){F.state='free';}
 }else if(F.state==='down'){F.vx*=Math.max(0,1-dt*6);F.vz*=Math.max(0,1-dt*6);if(F.st>.75){F.state='free';F.st=0;}}
 else if(F.state==='ko'){F.vx*=Math.max(0,1-dt*3);F.vz*=Math.max(0,1-dt*3);yawT=T.yaw;F.dis=F.st>1.2?Math.min(1,(F.st-1.2)/1.6):0;}
 else if(F.state==='win'){F.vx*=.9;F.vz*=.9;}
 // physics
 T.pos[0]+=F.vx*dt;T.pos[2]+=F.vz*dt;
 if(F.air||F.y>0){F.y+=F.vy*dt;F.vy-=G_*dt;if(F.y<=0){F.y=0;F.vy=0;if(F.air&&F.state==='free'){F.air=false;burst([T.pos[0],.05,T.pos[2]],10,3,[.8,.8,.8],[.5,.5,.5],.4,2.5,-2);}
   else if(F.air){F.air=false;burst([T.pos[0],.05,T.pos[2]],24,5,[.8,.8,.8],[.5,.5,.5],.5,2.5,-2);CAM.shake=Math.max(CAM.shake,.06);}}}
 T.pos[1]=F.y;
 if(F.state!=='ko'||F.st<.3)T.yaw=lerpAngle(T.yaw,yawT,Math.min(1,dt*(F.state==='free'?12:6)));
 targetHot(F);
 for(let i=0;i<NB;i++)F.hot[i]+=(F.hotT[i]-F.hot[i])*Math.min(1,dt*18);
 if(F.dis>0&&F.state!=='ko')F.dis=Math.max(0,F.dis-dt*2);
}
function separate(aT,a,bT,b,arena){
 if(a.y>1.3||b.y>1.3)return;
 const dx=bT.pos[0]-aT.pos[0],dz=bT.pos[2]-aT.pos[2],d=Math.hypot(dx,dz)||1e-3,min=.42*(a.S+b.S)+.2;
 if(d<min){const m=(min-d)/2,nx=dx/d,nz=dz/d;aT.pos[0]-=nx*m;aT.pos[2]-=nz*m;bT.pos[0]+=nx*m;bT.pos[2]+=nz*m;}
 for(const T of [aT,bT]){const r=Math.hypot(T.pos[0],T.pos[2]);if(r>arena){T.pos[0]*=arena/r;T.pos[2]*=arena/r;}}}
// ----- AI -----
function aiThink(e,oe,dt){
 const T=e.get('Transform'),F=e.get('Fighter'),oT=oe.get('Transform'),O=oe.get('Fighter'),ai=F.ai,A=F.A,I=F.in;
 ai.t-=dt;ai.mt-=dt;
 const dx=oT.pos[0]-T.pos[0],dz=oT.pos[2]-T.pos[2],d=Math.hypot(dx,dz)||1,nx=dx/d,nz=dz/d,lv=ai.lvl;
 if(M.state!=='fight'||F.state==='ko'){I.mx=I.mz=0;I.block=false;return;}
 const pw1=PW[A.pw[0]],pw2=PW[A.pw[1]];
 if(ai.t<=0){ai.t=rnd(.1,.3)*(1.4-lv*.6);
  const threat=O.state==='atk'&&d<2.6;
  if(threat&&Math.random()<.35+.4*lv){ai.mode='block';ai.mt=.35;}
  else if(ai.mt<=0){const r=Math.random(),reach=1.55*A.reach*A.S;
   if(d<reach){ if(F.en>=pw2.cost&&r<.14*A.aggr+.08)ai.mode='pw2';else if(r<.6)ai.mode='punch';else if(r<.8)ai.mode='kick';else if(r<.9)ai.mode='retreat';else ai.mode='strafe';ai.mt=.25;}
   else if(d>A.ideal+1.2){ if(F.en>=pw1.cost&&r<.45)ai.mode='pw1';else if(r<.15&&F.en>=pw2.cost&&A.ideal>2)ai.mode='pw2';else if(r<.25)ai.mode='jump';else ai.mode='approach';ai.mt=.35;}
   else { if(A.ideal>2&&d<A.ideal-.6){ai.mode='retreat';}else ai.mode=r<.55?'approach':(r<.8?'strafe':'idle');ai.mt=.3;}
  }
  aiPickExtra(e,oe,ai);}
 I.mx=I.mz=0;I.block=false;
 const sx=-nz,sz=nx;
 switch(ai.mode){
  case 'crystal':aiCrystalMove(e,I);break;
  case 'approach':I.mx=nx;I.mz=nz;break;case 'retreat':I.mx=-nx;I.mz=-nz;break;
  case 'strafe':{const s=(ai.ph||(ai.ph=Math.random()<.5?1:-1));I.mx=sx*s*.9+nx*.2;I.mz=sz*s*.9+nz*.2;break;}
  case 'block':I.block=true;break;
  case 'jump':I.press.jump=1;ai.mode='approach';break;
  case 'punch':I.press.punch=1;if(Math.random()<.5*lv)ai.t=.06;ai.mode='idle';break;
  case 'kick':I.press.kick=1;ai.mode='idle';break;
  case 'pw1':I.press.p1=1;ai.mode='idle';break;case 'pw2':I.press.p2=1;ai.mode='idle';break;}
 if(ai.t<.02)ai.ph=0;}
// ----- rounds -----
function placeFighters(){const a=world.entities[0],b=world.entities[1];
 for(const [e,x,yaw] of [[a,-2.6,Math.PI/2],[b,2.6,-Math.PI/2]]){const T=e.get('Transform'),F=e.get('Fighter');
  T.pos=[x,0,0];T.yaw=yaw;F.hp=F.max;F.state='free';F.st=0;F.vx=F.vz=F.vy=F.y=0;F.air=false;F.dis=0;F.freeze=0;F.slow=0;F.combo=0;F.en=Math.max(F.en,30);F.mv=null;F.flash=0;F.burst=0;F.pulse=0;}
 PROJ.length=0;GFX.length=0;resetRoundExtras();}
function startRound(){placeFighters();M.state='intro';M.st=0;M.timer=99;M.msg=(M.boss&&!M.twoP?'BOSS · ':'')+'ROUND '+M.round;}
function endRound(winner,loser){M.state='ko';M.st=0;M.msg='K.O.';
 const wi=winner.slot;M.wins[wi]++;winner.state='win';winner.st=0;HITSTOP=.35;CAM.shake=.25;}
function timeUp(){const a=world.entities[0].get('Fighter'),b=world.entities[1].get('Fighter');
 if(a.hp===b.hp){M.state='ko';M.st=0;M.msg='DRAW';return;}
 const w=a.hp>b.hp?a:b,l=a.hp>b.hp?b:a;l.hp=0;endRound(w,l);M.msg='TIME UP';}
function sysMatch(dt){
 if(M.mode!=='FIGHT')return;
 M.st+=dt;M.msgT-=dt;
 const a=world.entities[0].get('Fighter'),b=world.entities[1].get('Fighter');
 if(M.state==='intro'){if(M.st>1.1&&M.msg.indexOf('FIGHT')<0&&M.msg!=='FIGHT!'){M.msg='FIGHT!';}if(M.st>1.8){M.state='fight';M.st=0;M.msg='';}}
 else if(M.state==='fight'){M.timer-=dt;if(M.timer<=0)timeUp();}
 else if(M.state==='ko'){if(M.st>3){
   if(M.wins[0]>=2||M.wins[1]>=2){M.state='over';M.st=0;const p1w=M.wins[0]>=2;M.msg=p1w?'YOU WIN':(M.twoP?'PLAYER 2 WINS':'DEFEATED');onMatchWon(p1w);}
   else{M.round++;startRound();}}}
 else if(M.state==='over'){if(M.st>3.5){const p1w=M.wins[0]>=2;M.wins=[0,0];M.round=1;
   if(p1w&&!M.twoP&&!M.auto1){advanceLadder();}
   a.en=30;b.en=30;setArch(world.entities[0],ALL_KEYS[M.p1]);startRound();}}
}

// ===== ADDITIONS v2: CHARACTER SELECT · DOUBLE-PRESS WUXIA MOVES · CRYSTAL MEGA SWORD · ATON RA BOSS =====
const TAU=Math.PI*2,CHORD_AGE=.12,SWL=1.9;
const NOTE={s:'',t:0};function note(s,t){NOTE.s=s;NOTE.t=t||2.4;}
function rb(h,k){h=((h%1)+1)%1;k=k===undefined?1.4:k;const r=Math.abs(h*6-3)-1,g=2-Math.abs(h*6-2),b=2-Math.abs(h*6-4);return [clamp(r,0,1)*k,clamp(g,0,1)*k,clamp(b,0,1)*k];}
// ----- progress (ATON RA unlock) -----
const PROG={aton:false,def:{}};
try{const s=JSON.parse(localStorage.getItem('particleFighters.v2')||'null');if(s){PROG.aton=!!s.aton;PROG.def=s.def||{};}}catch(_){}
function saveProg(){try{localStorage.setItem('particleFighters.v2',JSON.stringify(PROG));}catch(_){}}
function unlockAton(){PROG.aton=true;saveProg();note('★ ATON RA UNLOCKED ★',3);}
function onMatchWon(p1w){
 if(!p1w||M.twoP||M.auto1)return;
 if(M.opp===6){note('ATON RA DEFEATED',3.2);return;}
 PROG.def[ALL_KEYS[M.opp]]=1;const n=ARCH_KEYS.filter(k=>PROG.def[k]).length;
 if(n>=ARCH_KEYS.length){if(!PROG.aton){PROG.aton=true;note('★ ALL DEFEATED · ATON RA UNLOCKED ★',4);}else note('ALL FIGHTERS DEFEATED',3);}
 else note('FIGHTERS DEFEATED '+n+'/6',2.4);
 saveProg();}
function advanceLadder(){
 const e1=world.entities[1];
 if(M.opp===6){PROG.def={};saveProg();M.opp=1;M.boss=false;M.ladder=1;setArch(e1,ARCH_KEYS[1]);return;}
 let nx=-1;for(let i=1;i<=6;i++){const k=(M.opp+i)%6;if(!PROG.def[ARCH_KEYS[k]]){nx=k;break;}}
 if(nx<0){M.opp=6;M.boss=true;note('WARNING · ATON RA APPROACHES',3.6);}else{M.opp=nx;M.boss=false;}
 M.ladder++;setArch(e1,ALL_KEYS[M.opp]);}
function toggleAuto1(){M.auto1=!M.auto1;world.entities[0].get('Fighter').ai.lvl=.75;statusMsg(M.auto1?'P1 = CPU AUTOPLAY':'P1 = MANUAL');}
// ----- double-press (two-button) wuxia moves, per-character flavour -----
