 dpS:ov(S0,[0,-.12,0],{rThigh:[-1.5,0,-.15],rShin:[.12,0,0],rFoot:[.5,0,0],lThigh:[-.05,0,.05],lShin:[.3,0,0],spine:[-.2,0,0],chest:[-.18,0,0],rArm:[.15,0,-1.5],lArm:[.15,0,1.5],rFore:[.15,0,0],lFore:[.15,0,0],head:[.05,0,0]}),
 dpFW:ov(S0,[0,-.34,0],{rArm:[.5,0,-.3],lArm:[.5,0,.3],rFore:[.8,0,0],lFore:[.8,0,0],rThigh:[-.9,0,-.1],rShin:[1.5,0,0],lThigh:[-.7,0,.1],lShin:[1.4,0,0],spine:[.3,0,0],chest:[.2,0,0]}),
