 dpDW:ov(S0,[0,-.3,0],{rArm:[-.6,0,-.4],lArm:[-.6,0,.4],rFore:[.5,0,0],lFore:[.5,0,0],rThigh:[-.8,0,-.1],rShin:[1.4,0,0],lThigh:[-.5,0,.1],lShin:[1.2,0,0],spine:[.35,0,0],chest:[.25,0,0]}),
