ATK.beam={w:'beamW',k:'beam'};
function dpPose(F,t){const m=F.mdef,s=F.st,B=stance(t);let p;
 if(m.dp==='spin'){
  if(s<m.st)p=mixPose(B,POSES.dpSW,smooth(s/m.st));
  else if(s<m.en){const u=(s-m.st)/(m.en-m.st);p=copyPose(mixPose(POSES.dpSW,POSES.dpS,smooth(u*6)));p.rot.hips=[.05,u*TAU*2,0];p.root=[0,p.root[1]+.14*Math.sin(u*Math.PI),0];}
  else p=mixPose(POSES.dpS,B,smooth((s-m.en)/(m.dur-m.en)));}
 else if(m.dp==='flip'){
  const u=clamp((s-m.st)/.8,0,1);
  if(s<m.st)p=mixPose(B,POSES.dpFW,smooth(s/m.st));
  else{p=copyPose(mixPose(POSES.dpFW,POSES.dpF,smooth(u*5)));
   const kk=Math.max(0,1-Math.abs(u-.5)*4.5);if(kk>0){p.rot.rThigh=[p.rot.rThigh[0]-1.0*kk,0,-.1];p.rot.rShin=[p.rot.rShin[0]*(1-kk)+.1*kk,0,0];}
   if(u>.82)p=copyPose(mixPose(p,B,smooth((u-.82)/.18)));
   const f=smooth(clamp((u-.04)/.9,0,1));p.rot.hips=[f<.5?-TAU*f:TAU*(1-f),0,0];}}
 else{
  if(s<m.st)p=mixPose(B,POSES.dpDW,smooth(s/m.st));
  else if(F.dpLand===null||F.dpLand===undefined){p=copyPose(mixPose(POSES.dpDW,POSES.dpD,smooth((s-m.st)/.1)));p.rot.hips=[-.8+.08*Math.sin(s*18),0,0];}
  else p=mixPose(POSES.dpD,B,smooth((s-F.dpLand)/.26));}
 return p;}
function chordPick(F){let id=null;
 if(F.dpReq){id=F.dpReq;F.dpReq=null;}
 else if(F.buf.punch>0&&F.buf.kick>0)id='dpS';
 else if(F.buf.kick>0&&F.buf.jump>0)id='dpF';
 else if(F.buf.punch>0&&F.buf.jump>0)id='dpD';
 if(!id)return null;
 if(F.dpCd>0||F.en<MV[id].cost||M.state!=='fight')return null;
 if(id==='dpS')F.buf.punch=F.buf.kick=0;else if(id==='dpF')F.buf.kick=F.buf.jump=0;else F.buf.punch=F.buf.jump=0;
 return id;}
function startDP(F,id){F.en-=MV[id].cost;F.dpCd=.7;startAtk(F,id);F.vx*=.3;F.vz*=.3;}
function dpCancel(F){const m=F.mdef;if(!m||m.pw||m.dp||F.st<=m.en)return false;const id=chordPick(F);if(!id)return false;startDP(F,id);return true;}
function pcol(X,i){const m=i%3;return m===0?rb(world.t*.9+i*.07,1.6):(m===1?X.c1:X.c2);}
function ringBurst(pos,R,n,X,up){for(let i=0;i<n;i++){const a=Math.random()*TAU;emit([pos[0]+Math.cos(a)*R*.15,pos[1]+.1,pos[2]+Math.sin(a)*R*.15],[Math.cos(a)*R*3,rnd(.5,3)*up,Math.sin(a)*R*3],pcol(X,i),rnd(.4,.8),3.2,2,2);}}
function footPos(e,b){const T=e.get('Transform'),F=e.get('Fighter'),R=e.get('Rig');return wBone(T,F,R,BIDX[b]);}
function wBone(T,F,R,b){return [T.pos[0]+(R.pos[b*3]-T.pos[0])*F.S,T.pos[1]+(R.pos[b*3+1]-T.pos[1])*F.S,T.pos[2]+(R.pos[b*3+2]-T.pos[2])*F.S];}
function flipShot(F,T,O,oT,X){
 const a=F,aT=T,o=O,A=F.A,mk=(p)=>spawnProj(a,aT,o,oT,p);
 switch(X.fl){
  case 'shots':{const b=aimDir(aT,oT,o,a);for(let i=-1;i<=1;i++){const an=i*.2,c=Math.cos(an),s=Math.sin(an);mk({dir:V3.norm([b[0]*c-b[2]*s,b[1],b[0]*s+b[2]*c]),spd:15,r:.2,dmg:6,c1:X.c1,c2:X.c2,kb:2,stun:.22,n:2200,tail:1.4,home:1});}break;}
  case 'fire':mk({spd:9,r:.5,dmg:13,c1:[1.6,.4,.05],c2:[1.7,1.4,.3],kb:5,stun:.34,n:5500,tail:1.3,heavy:1});break;
  case 'shards':{const b=aimDir(aT,oT,o,a);for(let i=-1;i<=1;i++){const an=i*.22,c=Math.cos(an),s=Math.sin(an);mk({dir:V3.norm([b[0]*c-b[2]*s,b[1],b[0]*s+b[2]*c]),spd:16,r:.17,dmg:5,c1:X.c1,c2:X.c2,kb:2,stun:.22,slow:1.5,n:1800,tail:1.5});}break;}
  case 'bolt':{const c=chestPos(aT,a,.5),tg=[oT.pos[0],oT.pos[1]+1.2*o.S+o.y*.5,oT.pos[2]];bolt(c,tg);if(!(o.y>1.3))applyHit(aT,a,oT,o,{dmg:11*A.dmg,kb:2.5,stun:.35,pw:1});GFX.push({type:'flash',pos:tg,t:0,dur:.3,c1:X.c1,c2:X.c2});break;}
  case 'orb':mk({spd:5,r:.46,dmg:12,c1:X.c1,c2:X.c2,kb:3,stun:.5,home:2.8,life:4,n:5500,heavy:1});break;
  case 'boulder':{const d=aimDir(aT,oT,o,a);mk({spd:9.5,r:.6,dmg:15,c1:[.4,.35,.25],c2:[.5,1.2,.4],kb:6,stun:.45,grav:9,dir:V3.norm([d[0],.5,d[2]]),n:5000,tail:.5,heavy:1});break;}
  case 'solar':{const b=aimDir(aT,oT,o,a);for(let i=-1;i<=1;i++){const an=i*.25,c=Math.cos(an),s=Math.sin(an);mk({dir:V3.norm([b[0]*c-b[2]*s,b[1],b[0]*s+b[2]*c]),spd:11,r:.36,dmg:9,c1:X.c1,c2:X.c2,kb:3.5,stun:.3,n:3200,tail:1.2,heavy:1});}break;}
  default:mk({spd:13,r:.34,dmg:10,c1:X.c1,c2:X.c2,kb:4,stun:.3,n:4000,heavy:1});}}
function dpLand(F,T,O,oT,X,sw){
 const fl=X.fl,pos=[T.pos[0],.05,T.pos[2]];
 const C={shock:{R:2.4,dmg:7,l:3.5},quake:{R:3.4,dmg:10,l:4.8},freeze:{R:2.6,dmg:7,l:0,fr:1.1},bolt:{R:2.8,dmg:8,l:3.5},pull:{R:3,dmg:8,l:3},solar:{R:3.6,dmg:13,l:5.5}}[fl]||{R:2.4,dmg:7,l:3.5};
 GFX.push({type:'ring',pos:pos,t:0,dur:.55,rr:C.R*1.25,c1:X.c1,c2:X.c2,h:.9});GFX.push({type:'ring',pos:pos,t:0,dur:.8,rr:C.R*.9,c1:rb(world.t*.9,1.6),c2:X.c2,h:1.4});
 ringBurst(pos,C.R,70,X,1);CAM.shake=Math.max(CAM.shake,fl==='quake'?.22:.12);
 if(fl==='bolt')for(let i=0;i<6;i++){const a=i/6*TAU+rnd(0,1);bolt([pos[0],.3,pos[2]],[pos[0]+Math.cos(a)*C.R,.3,pos[2]+Math.sin(a)*C.R]);}
 if(!F.hitDone&&O.state!=='ko'&&O.y<1.2&&dist2(T,oT)<C.R+.3*O.S){F.hitDone=true;applyHit(T,F,oT,O,{dmg:C.dmg*F.A.dmg*(sw?1.5:1),kb:4,stun:.45,launch:C.l,freeze:C.fr||0,pw:0,heavy:1});}}
function updateDP(e,oe,F,T,O,oT,dt,m){
 const X=(DPX[F.key]||DPX.op)[m.dp],fd=faceDir(T),sw=F.sword>0;
 const dx=oT.pos[0]-T.pos[0],dz=oT.pos[2]-T.pos[2],d=Math.hypot(dx,dz)||1,nx=dx/d,nz=dz/d;
 if(m.dp==='spin'){
  if(F.st<m.st){F.vx*=.9;F.vz*=.9;}
