   const adv=d>1.2*F.S?2.4:0,k=Math.min(1,dt*6);F.vx+=(nx*adv-F.vx)*k;F.vz+=(nz*adv-F.vz)*k;
   const R=m.reach*(sw?1.3:1)*F.S,ph=world.t*14;
   for(let i=0;i<26;i++){const a=ph+i/26*TAU*2,r=R*(.55+.45*Math.random());emit([T.pos[0]+Math.cos(a)*r,T.pos[1]+(.2+Math.random()*1.5)*F.S,T.pos[2]+Math.sin(a)*r],[-Math.sin(a)*5,rnd(-.5,1.5),Math.cos(a)*5],pcol(X,i),.35+Math.random()*.25,3.2,1.5,0);}
   for(const b of ['rFoot','lFoot']){const p=wBone(T,F,e.get('Rig'),BIDX[b]);for(let k2=0;k2<4;k2++)emit(p,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],rb(world.t+k2*.2,1.8),.35,3.4,3,0);}
   F.tick-=dt;
   if(F.tick<=0){F.tick=.15;const last=F.st>m.en-.2;
    if(d<R+.3*O.S&&O.y<1.6&&O.state!=='ko'){
     applyHit(T,F,oT,O,{dmg:(last?7:4.5)*F.A.dmg*(sw?1.5:1),kb:last?5:1.6,stun:.26,launch:last?5.5:0,slow:X.fl==='slow'?1.4:0,pw:0,heavy:last});
     if(X.fl==='chain')bolt(chestPos(T,F,.4),[oT.pos[0],oT.pos[1]+1.2*O.S+O.y*.5,oT.pos[2]]);
     if(X.fl==='burn')burst([oT.pos[0],oT.pos[1]+1.1*O.S,oT.pos[2]],24,6,[1.6,.5,.1],[1.7,1.4,.3],.5,3.4,-2);
     if(X.fl==='solar')burst([oT.pos[0],oT.pos[1]+1.1*O.S,oT.pos[2]],24,7,[1.9,.6,.05],[1.9,1.7,.5],.5,3.5,0);
     if(X.fl==='quake')CAM.shake=Math.max(CAM.shake,.12);}
    if(X.fl==='pull'&&d>1.1&&O.state!=='ko'){oT.pos[0]-=nx*.3;oT.pos[2]-=nz*.3;}}}}
 else if(m.dp==='flip'){
  if(!F.spawned&&F.st>=m.st){F.spawned=true;F.vy=9.6;F.air=true;F.inv=.5;F.vx=-fd[0]*4.6;F.vz=-fd[1]*4.6;F.dpApex=false;burst([T.pos[0],.1,T.pos[2]],24,4,X.c1,X.c2,.4,3,0);}
  if(F.spawned){
   const R=e.get('Rig');
   for(const b of ['rFoot','lFoot','rHand','lHand']){const p=wBone(T,F,R,BIDX[b]);for(let k=0;k<3;k++)emit(p,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],pcol(X,k+(b.length)),.45,3.4,2,0);}
   if(!F.dpApex&&F.vy<=1.5){F.dpApex=true;
    if(d<2.3*F.S+.3&&O.y<1.7&&O.state!=='ko')applyHit(T,F,oT,O,{dmg:8*F.A.dmg*(sw?1.5:1),kb:3,stun:.4,launch:5.2,pw:0,heavy:1});
    GFX.push({type:'ring',pos:[T.pos[0],T.pos[1]+.6,T.pos[2]],t:0,dur:.5,rr:2,c1:X.c1,c2:X.c2,h:.5});
    flipShot(F,T,O,oT,X);}
   if(!F.air&&F.y<=0&&F.st>m.st+.2){F.st=m.dur;burst([T.pos[0],.05,T.pos[2]],20,4,X.c1,X.c2,.4,3,-1);}
   if(F.st>m.st+1.4)F.st=m.dur;}}
 else{
  if(!F.spawned&&F.st>=m.st){F.spawned=true;const sp=clamp(d*1.7,4.5,10.5);F.vx=nx*sp;F.vz=nz*sp;F.vy=7.6;F.air=true;F.dpLand=null;F.hitDone=false;burst([T.pos[0],.1,T.pos[2]],30,5,X.c1,X.c2,.4,3,0);}
  if(F.spawned&&F.air){
   const sp0=clamp(d*1.7,3,9),k=Math.min(1,dt*2.2);F.vx+=(nx*sp0-F.vx)*k;F.vz+=(nz*sp0-F.vz)*k;
   const c=[T.pos[0],T.pos[1]+.9*F.S,T.pos[2]];
   for(let i=0;i<22;i++)emit([c[0]+rnd(-.2,.2),c[1]+rnd(-.5,.5),c[2]+rnd(-.2,.2)],[-F.vx*.25+rnd(-1,1),rnd(-1,1),-F.vz*.25+rnd(-1,1)],pcol(X,i),.5,3.6,2,0);
   if(!F.hitDone&&d<1.45*F.S+.3*O.S&&O.y<1.7&&O.state!=='ko'){F.hitDone=true;
    applyHit(T,F,oT,O,{dmg:m.dmg*F.A.dmg*(sw?1.4:1),kb:m.kb,stun:m.stun,freeze:X.fl==='freeze'?1.0:0,heavy:1});
    if(X.fl==='bolt')bolt(chestPos(T,F,.4),[oT.pos[0],oT.pos[1]+1.2*O.S,oT.pos[2]]);}}
  if(F.spawned&&!F.air&&F.y<=0&&(F.dpLand===null||F.dpLand===undefined)){F.dpLand=F.st;F.vx=F.vz=0;dpLand(F,T,O,oT,X,sw);}
  if(F.dpLand!==null&&F.dpLand!==undefined&&F.st>=F.dpLand+.28)F.st=m.dur;}}
function slashFx(T,F,id){GFX.push({type:'slash',t:0,dur:.28,pos:[T.pos[0],T.pos[1]+1.1*F.S+F.y,T.pos[2]],yaw:T.yaw,tilt:id==='p3'?0:(id==='k1'?-.55:rnd(-.6,.6)),S:F.S});}
// ----- crystal + particle mega sword -----
const CRY={on:false,pos:[0,0,0],t:0,life:0,next:6};
function crystalY(){const f=clamp(CRY.t/.9,0,1);return 1.05+(1-f*f)*8+Math.sin(world.t*2.4)*.12*f;}
function spawnCrystal(){const a=Math.random()*TAU,tp=M.mode==='TPS',r=tp?rnd(14,38):rnd(1.2,5.6),o=tp?world.entities[0].get('Transform').pos:[0,0,0];CRY.on=true;CRY.pos=[o[0]+Math.cos(a)*r,0,o[2]+Math.sin(a)*r];CRY.t=0;CRY.life=16;note('✦ SPECIAL CRYSTAL ✦',1.8);statusMsg('GRAB THE CRYSTAL · 20s PARTICLE MEGA SWORD');
 for(let i=0;i<60;i++)emit([CRY.pos[0],rnd(0,8),CRY.pos[2]],[rnd(-1,1),rnd(-1,1),rnd(-1,1)],rb(Math.random(),1.6),.8,3,1,0);}
function giveSword(e){const F=e.get('Fighter'),T=e.get('Transform');F.sword=20;F.swTip=null;
 burst([T.pos[0],T.pos[1]+1.2*F.S,T.pos[2]],120,10,[1.9,1.9,1.9],rb(Math.random(),1.8),1,3.6,0);CAM.shake=Math.max(CAM.shake,.15);
 GFX.push({type:'ring',pos:[T.pos[0],.05,T.pos[2]],t:0,dur:.7,rr:3,c1:rb(world.t,1.6),c2:[1.9,1.8,1],h:1});
 note('◆ '+(F.slot===0?'P1':(M.twoP?'P2':'CPU'))+' MEGA SWORD · 20s ◆',2.2);}
function swordFade(e,F,T){burst([T.pos[0],T.pos[1]+1.2*F.S,T.pos[2]],100,8,[1.9,1.9,1.9],rb(Math.random(),1.8),.9,3.4,1);F.swTip=null;note('SWORD FADES',1.4);}
function boneAxis(R,b){return [R.mats[b*16+4],R.mats[b*16+5],R.mats[b*16+6]];}
function swordFrame(e){const T=e.get('Transform'),F=e.get('Fighter'),R=e.get('Rig'),b=BIDX.rHand,ax=V3.norm(boneAxis(R,b)),p=wBone(T,F,R,b),base=V3.add(p,V3.scale(ax,.07*F.S));
 return {base:base,ax:ax,S:F.S,tip:V3.add(base,V3.scale(ax,SWL*F.S))};}
function resetRoundExtras(){CRY.on=false;CRY.next=rnd(5,9);for(const e of world.entities.slice(0,2)){const F=e.get('Fighter');F.sword=0;F.inv=0;F.dpCd=0;F.dpReq=null;F.swTip=null;F.dpLand=null;}}
function updateExtras(dt,w){
 if(M.mode!=='FIGHT'&&M.mode!=='TPS')return;
 const E=M.mode==='TPS'?[w.entities[0]]:[w.entities[0],w.entities[1]];
 if(M.state==='fight'){
  if(!CRY.on){CRY.next-=dt;if(CRY.next<=0)spawnCrystal();}
  else{CRY.t+=dt;CRY.life-=dt;const cy=crystalY();
   if(CRY.t>.85)for(const e of E){const F=e.get('Fighter'),T=e.get('Transform');if(F.state==='ko')continue;
    if(Math.hypot(T.pos[0]-CRY.pos[0],T.pos[2]-CRY.pos[2])<.85*F.S+.3&&cy>F.y-.3&&cy<F.y+2*F.S){giveSword(e);burst([CRY.pos[0],cy,CRY.pos[2]],90,9,[1.9,1.9,1.9],rb(Math.random(),1.8),.8,3.4,0);CRY.on=false;CRY.next=rnd(10,17);break;}}
   if(CRY.on&&CRY.life<=0){burst([CRY.pos[0],cy,CRY.pos[2]],50,5,[1.5,1.5,1.5],rb(Math.random(),1.5),.6,3,0);CRY.on=false;CRY.next=rnd(5,9);}
   else if(CRY.on&&Math.random()<.6)emit([CRY.pos[0]+rnd(-.3,.3),cy+rnd(-.4,.4),CRY.pos[2]+rnd(-.3,.3)],[rnd(-.4,.4),rnd(0,.8),rnd(-.4,.4)],rb(Math.random()+world.t*.3,1.7),.7,2.6,1,0);}}
 for(const e of E){const F=e.get('Fighter');
  if(F.sword>0&&F.state!=='ko'){const f=swordFrame(e),tip=f.tip,old=F.swTip;
   if(old){const L=V3.len(V3.sub(tip,old)),n=Math.min(16,2+Math.floor(L*12));for(let i=0;i<n;i++)emit(V3.lerp(old,tip,i/n),[rnd(-.6,.6),rnd(-.4,.9),rnd(-.6,.6)],rb(world.t*.7+i*.06,1.8),.38,3.2,2.2,0);}
   F.swTip=tip;}else F.swTip=null;}}
// ----- AI extras: crystal seeking + double-press moves (CPU triggers them directly, no buttons) -----
function aiPickExtra(e,oe,ai){
 const T=e.get('Transform'),F=e.get('Fighter'),oT=oe.get('Transform'),O=oe.get('Fighter'),A=F.A,lv=ai.lvl;
 if(M.state!=='fight'||F.state!=='free'||F.air)return;
 const d=dist2(T,oT),r=Math.random();
 if(CRY.on&&CRY.t>.8&&F.sword<=0){const cd=Math.hypot(CRY.pos[0]-T.pos[0],CRY.pos[2]-T.pos[2]),od=Math.hypot(CRY.pos[0]-oT.pos[0],CRY.pos[2]-oT.pos[2]);
  if((cd<od+2||d>2.8)&&r<.35+.5*lv){ai.mode='crystal';ai.mt=.35;return;}}
 const can=id=>F.dpCd<=0&&F.en>=MV[id].cost,sb=F.sword>0?.1:0;
 if(d<2.3*A.S&&can('dpS')&&r<.16*A.aggr+.05*lv+sb){F.in.dp='dpS';ai.mode='idle';ai.mt=.6;}
 else if(O.state==='atk'&&d<2.4&&can('dpF')&&r<.22*lv+.08){F.in.dp='dpF';ai.mode='idle';ai.mt=.6;}
 else if(d>2.6&&d<6.5&&can('dpD')&&r<.14*A.aggr+.04+sb){F.in.dp='dpD';ai.mode='idle';ai.mt=.6;}
 else if(F.sword>0&&d>2.2&&r<.6){ai.mode='approach';ai.mt=.3;}}
function aiCrystalMove(e,I){if(!CRY.on){e.get('Fighter').ai.mode='approach';return;}const T=e.get('Transform'),dx=CRY.pos[0]-T.pos[0],dz=CRY.pos[2]-T.pos[2],l=Math.hypot(dx,dz)||1;I.mx=dx/l;I.mz=dz/l;}
// ----- ATON RA: visor beam + eclipse -----
function beamOrigin(g){const R=g.e.get('Rig'),T=g.aT,S=g.a.S,hi=BIDX.head,hp=wBone(T,g.a,R,hi),up=boneAxis(R,hi),fd=faceDir(T);
 return [hp[0]+(up[0]*.17+fd[0]*.1)*S,hp[1]+up[1]*.17*S,hp[2]+(up[2]*.17+fd[1]*.1)*S];}
function updateGFXExt(g,dt){
 if(g.type==='beam'){
  const o=beamOrigin(g);g.org=o;const tg=[g.oT.pos[0],g.oT.pos[1]+1.1*g.o.S+g.o.y*.6,g.oT.pos[2]],want=V3.norm(V3.sub(tg,o));
  g.dir=g.dir?V3.norm(V3.lerp(g.dir,want,Math.min(1,dt*(g.t<.25?6:1.4)))):want;
  let L=16;if(g.dir[1]<-.01)L=Math.min(L,(o[1]-.03)/-g.dir[1]);
  const rel=V3.sub(tg,o),proj=V3.dot(rel,g.dir),cl=V3.add(o,V3.scale(g.dir,clamp(proj,0,L))),dd=V3.len(V3.sub(tg,cl));
  g.hit=proj>0&&proj<=L&&dd<.5*g.o.S+.28&&g.o.state!=='ko';if(g.hit)L=Math.min(L,proj+.15);g.L=L;
  const end=V3.add(o,V3.scale(g.dir,L));
  g.tick-=dt;if(g.hit&&g.tick<=0){g.tick=.19;const fin=g.t>g.dur-.25;applyHit(g.aT,g.a,g.oT,g.o,{dmg:(fin?12:5)*g.a.A.dmg,kb:fin?5:1.4,stun:.3,launch:fin?5.5:0,pw:1,heavy:fin});burst(end,22,8,[1.9,1.2,.2],[1.9,1.9,.7],.4,3.4,0);}
  for(let i=0;i<8;i++){const q=V3.add(o,V3.scale(g.dir,Math.random()*L));emit(q,[rnd(-1,1),rnd(-.5,1.5),rnd(-1,1)],Math.random()<.5?[1.9,1.1,.15]:[1.9,1.8,.6],.3,3,2,0);}
  if(end[1]<.2)burst([end[0],.1,end[2]],5,6,[1.9,1.1,.15],[1.9,1.8,.6],.4,3.2,0);CAM.shake=Math.max(CAM.shake,.05);}
 else if(g.type==='eclipse'){
  g.pos=[g.aT.pos[0],g.aT.pos[1]+1.0*g.a.S,g.aT.pos[2]];
  const dx=g.aT.pos[0]-g.oT.pos[0],dz=g.aT.pos[2]-g.oT.pos[2],d=Math.hypot(dx,dz)||1;
  if(g.t<.78&&g.o.state!=='ko'&&d>1.3){g.oT.pos[0]+=dx/d*2.6*dt;g.oT.pos[2]+=dz/d*2.6*dt;}
  if(!g.done&&g.t>.8){g.done=true;burst(g.pos,150,13,[1.9,1.1,.15],[1.9,1.9,.7],1,3.8,0);CAM.shake=Math.max(CAM.shake,.3);
   if(d<4.6*g.a.S&&g.o.state!=='ko')applyHit(g.aT,g.a,g.oT,g.o,{dmg:20*g.a.A.dmg,kb:6,stun:.5,launch:7.2,pw:1,heavy:1});}}}
function drawGFXExt(VP,g,k){
 if(g.type==='ring')drawFXC(VP,{mode:0,pos:g.pos,r:Math.max(.2,g.rr*smooth(Math.min(1,k*1.6))),h:g.h,t:k,a:Math.max(0,1-k*k),c1:g.c1,c2:g.c2,n:6500});
 else if(g.type==='eclipse'){
  if(g.t<.8)drawFXC(VP,{mode:3,pos:g.pos,r:3.2*g.a.S*(1-.3*k),h:0,t:k,a:1,c1:[1.9,.5,.05],c2:[1.9,1.7,.5],n:8000});
  else{const q=(g.t-.8)/.5;drawFXC(VP,{mode:2,pos:g.pos,r:Math.max(.2,q*5.2*g.a.S),h:0,t:Math.min(1,q),a:1,c1:[1.9,1,.1],c2:[1.9,1.9,.7],n:7500});drawFXC(VP,{mode:0,pos:[g.pos[0],0,g.pos[2]],r:Math.max(.2,q*5.4*g.a.S),h:1.2,t:Math.min(1,q),a:1,c1:[1.9,.5,.05],c2:[1.9,1.7,.5],n:6000});}}
 else if(g.type==='beam'&&g.org&&g.dir){
  const o=g.org,dir=g.dir,L=g.L||1,env=Math.min(1,g.t/.12)*Math.min(1,(g.dur-g.t)/.18),up=Math.abs(dir[1])>.95?[1,0,0]:[0,1,0],rt=V3.norm(V3.cross(dir,up)),u2=V3.cross(rt,dir),t=world.t;
  for(let i=0;i<620;i++){const u=Math.random(),p=V3.add(o,V3.scale(dir,u*L)),layer=i%4,rad=(layer===0?.035:layer===1?.11:layer===2?.2:.3)*(1+u*.35)*env,an=Math.random()*TAU+u*14-t*18;
   const c=layer===0?[2.1,2.0,1.2]:layer===1?[1.9,1.5,.35]:layer===2?[1.9,.8,.08]:[1.5,.3,.03];
   xp(p[0]+(rt[0]*Math.cos(an)+u2[0]*Math.sin(an))*rad,p[1]+(rt[1]*Math.cos(an)+u2[1]*Math.sin(an))*rad,p[2]+(rt[2]*Math.cos(an)+u2[2]*Math.sin(an))*rad,c,.85*env,layer===0?3.4:2.8);}
  const e2=V3.add(o,V3.scale(dir,L));for(let i=0;i<60;i++)xp(e2[0]+rnd(-.35,.35),e2[1]+rnd(-.35,.35),e2[2]+rnd(-.35,.35),[1.9,1.4,.3],.9*env,3.6);
  for(let i=0;i<30;i++)xp(o[0]+rnd(-.12,.12),o[1]+rnd(-.12,.12),o[2]+rnd(-.12,.12),[2,1.8,.9],env,4);}
 else if(g.type==='slash'){
  const pr=smooth(Math.min(1,k*2.4)),fd=[Math.sin(g.yaw),Math.cos(g.yaw)],rt=[fd[1],-fd[0]];
  for(let i=0;i<140;i++){const f=i/140,th=(-1.15+2.3*f)*pr,R=1.7*g.S*(1+.15*Math.random());
   xp(g.pos[0]+fd[0]*Math.cos(th)*R+rt[0]*Math.sin(th)*R,g.pos[1]+g.tilt*Math.sin(th)*R*.6+rnd(-.05,.05),g.pos[2]+fd[1]*Math.cos(th)*R+rt[1]*Math.sin(th)*R,rb(f+world.t*.8,1.9),(1-k)*.95*(.4+.6*f),3.2);}}}
// ----- particle props renderer (crystal, mega swords, TPS blaster for non-operator characters) -----
const EXTRA_MAX=8000,EXTRA=new Float32Array(EXTRA_MAX*8);let EN=0,extraVbo=null;
function xp(x,y,z,c,a,s){if(EN>=EXTRA_MAX)return;const o=EN*8;EXTRA[o]=x;EXTRA[o+1]=y;EXTRA[o+2]=z;EXTRA[o+3]=c[0];EXTRA[o+4]=c[1];EXTRA[o+5]=c[2];EXTRA[o+6]=a;EXTRA[o+7]=s;EN++;}
function drawSword(e){const F=e.get('Fighter'),f=swordFrame(e),t=world.t,L=SWL*f.S,fl=F.sword<3?(Math.sin(t*40)>0?1:.35):1,ax=f.ax;
 let side=V3.cross(ax,[0,1,0]);if(V3.len(side)<.2)side=[1,0,0];side=V3.norm(side);const nrm=V3.cross(ax,side),b=f.base;
 for(let i=0;i<360;i++){const u=Math.random(),w=(.085*(1-Math.pow(u,2.2))+.01)*f.S,sx=Math.random()*2-1,ed=Math.abs(sx)>.82,hue=u*.9+t*.45,off=sx*w,th=(Math.random()-.5)*.02*f.S;
  const c=ed?rb(hue,1.9):(Math.abs(sx)<.12?[2,2,1.8]:rb(hue+.12,1));
  xp(b[0]+ax[0]*u*L+side[0]*off+nrm[0]*th,b[1]+ax[1]*u*L+side[1]*off+nrm[1]*th,b[2]+ax[2]*u*L+side[2]*off+nrm[2]*th,c,.9*fl,ed?3.2:2.4);}
 for(let j=0;j<40;j++){const a=(Math.random()*2-1)*.17*f.S;xp(b[0]+side[0]*a,b[1]+side[1]*a,b[2]+side[2]*a,[1.9,1.4,.3],fl,2.8);}
 for(let j=0;j<30;j++){const u=Math.random();xp(b[0]+ax[0]*u*L+rnd(-.2,.2),b[1]+ax[1]*u*L+rnd(-.2,.2),b[2]+ax[2]*u*L+rnd(-.2,.2),rb(Math.random()+t,1.8),Math.random()*.9*fl,3);}}
function drawCrystal(){if(!CRY.on)return;const t=world.t,cy=crystalY(),fall=clamp(CRY.t/.9,0,1),r=.38,ry=.6,ca=Math.cos(t*1.8),sa=Math.sin(t*1.8),fade=clamp(CRY.life/1.5,0,1);
 const V=[[r,0,0],[-r,0,0],[0,ry,0],[0,-ry,0],[0,0,r],[0,0,-r]],P=V.map(v=>[CRY.pos[0]+v[0]*ca-v[2]*sa,cy+v[1],CRY.pos[2]+v[0]*sa+v[2]*ca]);
 const E=[[0,2],[0,3],[1,2],[1,3],[4,2],[4,3],[5,2],[5,3],[0,4],[4,1],[1,5],[5,0]];
 E.forEach((ed,ei)=>{for(let i=0;i<16;i++){const u=i/16,p=V3.lerp(P[ed[0]],P[ed[1]],u);xp(p[0],p[1],p[2],rb(t*.6+ei*.08+u*.3,1.9),fade,3.4);}});
 const F=[[0,2,4],[4,2,1],[1,2,5],[5,2,0],[0,3,4],[4,3,1],[1,3,5],[5,3,0]];
 for(let i=0;i<140;i++){const f=F[i%8];let a=Math.random(),b2=Math.random();if(a+b2>1){a=1-a;b2=1-b2;}const c=1-a-b2,p=[P[f[0]][0]*a+P[f[1]][0]*b2+P[f[2]][0]*c,P[f[0]][1]*a+P[f[1]][1]*b2+P[f[2]][1]*c,P[f[0]][2]*a+P[f[1]][2]*b2+P[f[2]][2]*c];xp(p[0],p[1],p[2],rb(t*.5+i*.013,1.1),.7*fade,2.6);}
 const top=fall<1?cy+3:7;for(let i=0;i<70;i++){const h=Math.random(),an=h*20+t*3,rr=.1+.07*Math.sin(h*30+t*4);xp(CRY.pos[0]+Math.cos(an)*rr,h*top,CRY.pos[2]+Math.sin(an)*rr,rb(h+t*.4,1.5),(1-h)*.6*fade,2.4);}
 for(let i=0;i<40;i++){const a=i/40*TAU,rr=.9+.12*Math.sin(t*3+i);xp(CRY.pos[0]+Math.cos(a)*rr,.05,CRY.pos[2]+Math.sin(a)*rr,rb(a/TAU+t*.3,1.6),.8*fade,2.8);}}
function drawProps(VP){
 if(M.mode==='FIGHT'){drawCrystal();for(const e of world.entities.slice(0,2)){const F=e.get('Fighter');if(F.sword>0&&F.state!=='ko')drawSword(e);}}
 else{const e=world.entities[0],F=e.get('Fighter');if(F.key!=='op'){const T=e.get('Transform'),R=e.get('Rig'),gi=BIDX.gun,ax=V3.norm(boneAxis(R,gi)),b=wBone(T,F,R,gi),A=F.A;
   for(let i=0;i<120;i++){const u=Math.random(),th=Math.random()*TAU,rr=(u<.7?.035:.02)*F.S,sd=V3.norm(V3.cross(ax,[0,1,0]));
    xp(b[0]+ax[0]*u*.62*F.S+sd[0]*Math.cos(th)*rr,b[1]+ax[1]*u*.62*F.S+Math.sin(th)*rr,b[2]+ax[2]*u*.62*F.S+sd[2]*Math.cos(th)*rr,u>.85?A.pal.eye:A.pal.acc,.95,2.6);}}}
 if(!EN)return;const P=prog.pts;if(!extraVbo){extraVbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,extraVbo);gl.bufferData(gl.ARRAY_BUFFER,EXTRA.byteLength,gl.DYNAMIC_DRAW);}
 gl.useProgram(P.p);gl.uniformMatrix4fv(P.u.uVP,false,VP);gl.uniform3fv(P.u.uCam,CAM.eye);gl.uniform1f(P.u.uPt,DPRV);
 gl.bindBuffer(gl.ARRAY_BUFFER,extraVbo);gl.bufferSubData(gl.ARRAY_BUFFER,0,EXTRA.subarray(0,EN*8));
 bindA(P.a.aP,extraVbo,3,32,0);bindA(P.a.aC,extraVbo,4,32,12);bindA(P.a.aS,extraVbo,1,32,28);gl.drawArrays(gl.POINTS,0,EN);
 gl.disableVertexAttribArray(P.a.aP);gl.disableVertexAttribArray(P.a.aC);gl.disableVertexAttribArray(P.a.aS);}
// ----- character select (works for 1P / 2P / 3RD PERSON, keyboard, mouse/touch, any pad) -----
const SEL={open:false,who:0,cur:[0,1],done:[false,false],stick:[0,0]};
function openSel(){if(!world)return;SEL.open=true;SEL.who=0;SEL.cur=[M.p1,M.opp];SEL.done=[false,false];statusMsg('CHARACTER SELECT');}
function closeSel(){SEL.open=false;statusMsg(M.mode==='FIGHT'?'FIGHT! · X = CHARACTER SELECT':'3RD PERSON · X = CHARACTER SELECT');}
function selMove(d){SEL.cur[SEL.who]=(SEL.cur[SEL.who]+d+7)%7;}
function pickChar(who,i){
 if(i===6&&!PROG.aton){note('LOCKED · DEFEAT ALL 6 FIGHTERS TO UNLOCK ATON RA',2.6);return false;}
 if(who===0){M.p1=i;setArch(world.entities[0],ALL_KEYS[i]);}
 else{if(M.mode!=='FIGHT')return false;M.opp=i;M.boss=(i===6);setArch(world.entities[1],ALL_KEYS[i]);}
 if(M.mode==='FIGHT'){M.wins=[0,0];M.round=1;startRound();}
 statusMsg((who===0?'P1 · ':(M.twoP?'P2 · ':'CPU · '))+ARCH[ALL_KEYS[i]].name);return true;}
function selConfirm(){const w=SEL.who,two=M.twoP&&M.mode==='FIGHT';if(!pickChar(w,SEL.cur[w]))return;SEL.done[w]=true;
 if(two){if(SEL.done[0]&&SEL.done[1])closeSel();else SEL.who=w^1;}else closeSel();}
function selKey(k){
 const two=M.twoP&&M.mode==='FIGHT',cols=HUDR.selCols||4,mv=(who,d)=>{SEL.who=who;selMove(d);};
 if(k==='Escape'||k==='KeyX'){closeSel();return;}
 if(k==='Tab'){if(M.mode==='FIGHT')SEL.who^=1;return;}
 if(two){
  if(k==='KeyA')mv(0,-1);else if(k==='KeyD')mv(0,1);else if(k==='KeyW')mv(0,-cols);else if(k==='KeyS')mv(0,cols);
  else if(k==='ArrowLeft')mv(1,-1);else if(k==='ArrowRight')mv(1,1);else if(k==='ArrowUp')mv(1,-cols);else if(k==='ArrowDown')mv(1,cols);
  else if(k==='KeyJ'||k==='Space'||k==='KeyF'||k==='Enter'){SEL.who=0;selConfirm();}
  else if(k==='Comma'||k==='Period'||k==='Slash'||k==='Quote'){SEL.who=1;selConfirm();}}
 else{
  if(k==='KeyA'||k==='ArrowLeft')selMove(-1);else if(k==='KeyD'||k==='ArrowRight')selMove(1);else if(k==='KeyW'||k==='ArrowUp')selMove(-cols);else if(k==='KeyS'||k==='ArrowDown')selMove(cols);
  else if(k==='KeyJ'||k==='Space'||k==='KeyF'||k==='Enter'||k==='Comma')selConfirm();}}
function selInput(dt){
 const two=M.twoP&&M.mode==='FIGHT';
 for(let pi=0;pi<2&&SEL.open;pi++){const P=PADS[pi];if(!P.on)continue;const who=two?pi:SEL.who;SEL.stick[pi]-=dt;
  let dx=(pressed(P,15)?1:0)-(pressed(P,14)?1:0),dy=(pressed(P,13)?1:0)-(pressed(P,12)?1:0);
  if(!dx&&Math.abs(P.ax[0])>.6&&SEL.stick[pi]<=0){dx=P.ax[0]>0?1:-1;SEL.stick[pi]=.22;}
  if(!dy&&Math.abs(P.ax[1])>.6&&SEL.stick[pi]<=0){dy=P.ax[1]>0?1:-1;SEL.stick[pi]=.22;}
  if(dx||dy){SEL.who=who;selMove(dx+dy*(HUDR.selCols||4));}
  if(pressed(P,0)||pressed(P,2)||pressed(P,9)){SEL.who=who;selConfirm();}
  else if(pressed(P,1)||pressed(P,8))closeSel();
  else if(pressed(P,3)&&!two&&M.mode==='FIGHT')SEL.who^=1;}}
function cssC(c,k){k=k||.62;return 'rgb('+[0,1,2].map(i=>Math.round(clamp(c[i]*k,0,1)*255)).join(',')+')';}
function buildSelHUD(root,w,h){
 const g=el('g',{},root);HUDR.selG=g;const n=7,cols=Math.max(2,Math.min(7,Math.floor((w-24)/168))),rows=Math.ceil(n/cols),cw=Math.min(188,Math.floor((w-24-(cols-1)*8)/cols)),ch=118;
 HUDR.selCols=cols;const pw=cols*cw+(cols-1)*8+24,ph=70+rows*(ch+8)+10,px=(w-pw)/2,py=Math.max(6,(h-ph)/2);
 const pg=el('g',{transform:'translate('+px+','+py+')','pointer-events':'all'},g);
 pg.addEventListener('pointerdown',function(e){e.stopPropagation();});
 el('rect',{width:pw,height:ph,rx:10,class:'pnl pnlA',style:'fill:rgba(2,8,12,.94)'},pg);
 el('text',{x:14,y:24,class:'t1',text:'SELECT FIGHTER'},pg);
 HUDR.selHint=el('text',{x:14,y:42,class:'t2',text:'A/D/W/S OR ARROWS MOVE · J/ENTER/SPACE PICK · TAB SWITCH P1 / CPU-P2 · X/ESC CLOSE · PAD: D-PAD/STICK + A · CLICK/TAP A CARD'},pg);
 HUDR.selWho=[mkBtn(pg,pw-330,10,100,22,'PICK P1','btnA',function(){SEL.who=0;}),mkBtn(pg,pw-224,10,100,22,'PICK CPU','btnA',function(){if(M.mode==='FIGHT')SEL.who=1;}),mkBtn(pg,pw-118,10,106,22,'CLOSE','btn',closeSel)];
 HUDR.selCards=[];
 for(let i=0;i<n;i++){
  const key=ALL_KEYS[i],A=ARCH[key],X=DPX[key],col=cssC(A.pal.edge,.7),gx=12+(i%cols)*(cw+8),gy=56+Math.floor(i/cols)*(ch+8);
  const cg=el('g',{transform:'translate('+gx+','+gy+')','pointer-events':'all',style:'cursor:pointer'},pg),C={i:i};
  el('rect',{width:cw,height:ch,rx:6,fill:'rgba(8,26,30,.75)',stroke:'rgba(0,255,208,.25)'},cg);
  C.r1=el('rect',{width:cw,height:ch,rx:6,fill:'none',stroke:'#00ffd0','stroke-width':3},cg);C.r2=el('rect',{x:3,y:3,width:cw-6,height:ch-6,rx:5,fill:'none',stroke:'#ff5c8a','stroke-width':2.5},cg);
  C.ok=el('g',{},cg);
  el('text',{x:8,y:16,class:'t2',style:'fill:'+col+';font-weight:bold;font-size:11px',text:A.name},C.ok);
  [['HP',A.hp/230],['SPD',A.spd/1.4],['PWR',clamp(A.dmg*A.reach/1.9,0,1)]].forEach((s,j)=>{el('text',{x:8,y:29+j*8,class:'dim','font-size':7,text:s[0]},C.ok);
   el('rect',{x:30,y:24+j*8,width:cw-44,height:4,fill:'rgba(255,255,255,.08)'},C.ok);el('rect',{x:30,y:24+j*8,width:Math.max(3,(cw-44)*clamp(s[1],0,1)),height:4,fill:col},C.ok);});
  el('text',{x:8,y:60,class:'dim',text:'Y '+PW[A.pw[0]].n},C.ok);el('text',{x:8,y:71,class:'dim',text:'B '+PW[A.pw[1]].n},C.ok);
  el('text',{x:8,y:86,class:'amb','font-size':8,text:'P+K '+X.spin.n},C.ok);el('text',{x:8,y:97,class:'amb','font-size':8,text:'K+J '+X.flip.n},C.ok);el('text',{x:8,y:108,class:'amb','font-size':8,text:'P+J '+X.dive.n},C.ok);
  C.lock=el('g',{},cg);
  if(i===6){el('rect',{width:cw,height:ch,rx:6,fill:'rgba(0,0,0,.6)'},C.lock);el('text',{x:cw/2,y:44,'text-anchor':'middle',class:'t1','font-size':13,text:'ATON RA'},C.lock);el('text',{x:cw/2,y:62,'text-anchor':'middle',class:'amb',text:'LOCKED'},C.lock);
   el('text',{x:cw/2,y:78,'text-anchor':'middle',class:'dim',text:'DEFEAT ALL 6 FIGHTERS'},C.lock);C.prog=el('text',{x:cw/2,y:94,'text-anchor':'middle',class:'stat',text:''},C.lock);}
  C.b1=el('text',{x:cw-6,y:14,'text-anchor':'end',class:'stat','font-size':9,text:''},cg);C.b2=el('text',{x:cw-6,y:26,'text-anchor':'end',class:'amb','font-size':9,text:''},cg);
  cg.addEventListener('pointerdown',function(e){e.stopPropagation();});
  cg.addEventListener('click',function(){SEL.cur[SEL.who]=i;selConfirm();});
  cg.addEventListener('pointerenter',function(){SEL.cur[SEL.who]=i;});
  HUDR.selCards.push(C);}}
function updateSelHUD(){
 if(!HUDR.selG)return;HUDR.selG.style.display=SEL.open?'':'none';if(!SEL.open)return;
 const fight=M.mode==='FIGHT',two=M.twoP&&fight;
 HUDR.selCards.forEach(C=>{const i=C.i,lk=(i===6&&!PROG.aton);
  C.ok.style.display=lk?'none':'';C.lock.style.display=lk?'':'none';
  C.r1.style.display=SEL.cur[0]===i?'':'none';C.r1.setAttribute('stroke-width',SEL.who===0?3:1.5);
  C.r2.style.display=(fight&&SEL.cur[1]===i)?'':'none';C.r2.setAttribute('stroke-width',SEL.who===1?3:1.5);
  C.b1.textContent=M.p1===i?'P1':'';C.b2.textContent=(fight&&M.opp===i)?(M.twoP?'P2':'CPU'):'';
  if(C.prog)C.prog.textContent=ARCH_KEYS.filter(k=>PROG.def[k]).length+' / 6 DEFEATED';});
 HUDR.selWho.forEach((b,j)=>{if(j<2)b.classList.toggle('act',SEL.who===j);});
 HUDR.selWho[1].lastChild.textContent=two?'PICK P2':'PICK CPU';}
function updateHUDExtra(d,w){
 if(!HUDR.note)return;NOTE.t-=d;HUDR.note.textContent=NOTE.t>0?NOTE.s:'';
 const F=[w.entities[0].get('Fighter'),w.entities[1].get('Fighter')],fight=M.mode==='FIGHT';
 HUDR.bars.forEach((b,s)=>{if(!b.sw)return;const f=F[s],X=DPX[f.key]||DPX.op;
  b.sw.style.display=fight?'':'none';b.dp.style.display=(fight&&!HUDR.narrow)?'':'none';
  b.sw.textContent=f.sword>0?'◆ MEGA SWORD '+f.sword.toFixed(1)+'s':'';
  b.dp.textContent='P+K '+X.spin.n+' · K+J '+X.flip.n+' · P+J '+X.dive.n;});
 if(HUDR.bSel)HUDR.bSel.classList.toggle('act',SEL.open);if(HUDR.bAuto1)HUDR.bAuto1.classList.toggle('act',!!M.auto1);
 updateSelHUD();}
window.__FIGHT_EXT={PROG:PROG,unlockAton:unlockAton,CRY:CRY,SEL:SEL,spawnCrystal:spawnCrystal,giveSword:giveSword};

// ===== CLOUD MANAGER / INPUT / CAMERA / TPS / ANIM / RENDER =====
const CLOUDS={};let FPS=60,DRAWCALLS=0;
function ensureCloud(key){
 if(!gl)return;const N=TIERS[tierIdx],c=CLOUDS[key];
 if(c&&(c.N===N||c.building))return;
 if(c)c.building=true;else CLOUDS[key]={building:true,count:0,N:0,vbo:null,fade:0};
 statusMsg('ALLOCATING '+N.toLocaleString('en-US')+' PARTICLES · '+ARCH[key].name);
 setTimeout(function(){const t0=performance.now(),d=buildCloud(key,N),cc=CLOUDS[key];
  if(!cc.vbo)cc.vbo=[0,1,2,3].map(()=>gl.createBuffer());
  [d.pos,d.col,d.skin,d.ex].forEach((arr,i)=>{gl.bindBuffer(gl.ARRAY_BUFFER,cc.vbo[i]);gl.bufferData(gl.ARRAY_BUFFER,arr,gl.STATIC_DRAW);});
  cc.count=d.count;cc.N=N;cc.building=false;cc.fade=0;statusMsg(ARCH[key].name+' · '+N.toLocaleString('en-US')+' PTS · '+(performance.now()-t0).toFixed(0)+' MS');},30);}
function refreshClouds(){const used={};world.entities.slice(0,2).forEach(e=>{used[e.get('Fighter').key]=1;});
 for(const k in CLOUDS)if(!used[k]&&!CLOUDS[k].building){if(CLOUDS[k].vbo)CLOUDS[k].vbo.forEach(b=>gl.deleteBuffer(b));delete CLOUDS[k];}
 for(const k in used)ensureCloud(k);}
function cycleTier(d){tierIdx=(tierIdx+d+TIERS.length)%TIERS.length;refreshClouds();}
// ----- input -----
const KEY={},TOUCH={joy:{on:false,x:0,z:0},block:false,id:-1,bx:0,by:0};
const PADS=[{on:false,prev:[],ax:[0,0,0,0],btn:[],id:''},{on:false,prev:[],ax:[0,0,0,0],btn:[],id:''}];
const CAMMENU={open:false,sel:0,zoom:1,stickT:0};
let TOUCHMODE=COARSE,HELPSHOW=true,MENUSHOW=(typeof window!=='undefined'&&window.innerWidth>=900),FREEZE_ACT=false;
const SNAP=['plasma'];
function pollPads(){
 const list=navigator.getGamepads?navigator.getGamepads():[],c=[];
 for(let i=0;i<list.length;i++)if(list[i]&&list[i].connected)c.push(list[i]);
 for(let s=0;s<2;s++){const P=PADS[s],g=c[s];P.prevB=P.btn;
  if(!g){P.on=false;P.ax=[0,0,0,0];P.btn=[];continue;}
  const dz=v=>Math.abs(v)<.16?0:v;P.on=true;P.id=(g.id||'PAD').replace(/\(.*\)/,'').slice(0,20);
  P.ax=[dz(g.axes[0]||0),dz(g.axes[1]||0),dz(g.axes[2]||0),dz(g.axes[3]||0)];P.btn=g.buttons.map(b=>b.pressed||b.value>.6);}}
function pressed(P,i){return P.btn[i]&&!(P.prevB&&P.prevB[i]);}
function camBasis(){const f=[CAM.target[0]-CAM.eye[0],CAM.target[2]-CAM.eye[2]],l=Math.hypot(f[0],f[1])||1;f[0]/=l;f[1]/=l;return {f:f,r:[-f[1],f[0]]};}
function fighterInput(F,src,B){ // src: {mx,my,block,presses{}}
 const w=B.r[0]*src.mx+B.f[0]*src.my,z=B.r[1]*src.mx+B.f[1]*src.my;
 const l=Math.hypot(w,z);F.in.mx=l>1?w/l:w;F.in.mz=l>1?z/l:z;F.in.block=!!src.block;
 for(const k in src.press)if(src.press[k]){if(k==='dpS'||k==='dpF'||k==='dpD')F.in.dp=k;else F.in.press[k]=1;}}
const kbP1={},kbP2={};
function sysInput(dt,w){
 pollPads();const B=camBasis(),e0=w.entities[0],e1=w.entities[1],F0=e0.get('Fighter'),F1=e1.get('Fighter');
 // global pad actions (P1 pad)
 const p0=PADS[0];
 if(!SEL.open&&PADS[1].on&&pressed(PADS[1],10))openSel();
 if(p0.on&&!SEL.open){if(pressed(p0,10))openSel();if(pressed(p0,8))toggleCamMenu();if(pressed(p0,9))togglePause();if(pressed(p0,11)&&!CAMMENU.open)nextView();
  if(CAMMENU.open){CAMMENU.stickT-=dt;
   if(pressed(p0,12)||(p0.ax[1]<-.6&&CAMMENU.stickT<=0)){camMenuMove(-1);CAMMENU.stickT=.25;}
   if(pressed(p0,13)||(p0.ax[1]>.6&&CAMMENU.stickT<=0)){camMenuMove(1);CAMMENU.stickT=.25;}
   if(pressed(p0,14)||pressed(p0,15)){CAMMENU.zoom=clamp(CAMMENU.zoom+(pressed(p0,15)?.1:-.1),.6,1.6);}
   if(pressed(p0,0))toggleCamMenu();if(pressed(p0,1))toggleCamMenu();}}
 F0.in.mx=F0.in.mz=0;F0.in.block=false;F1.in.mx=F1.in.mz=0;F1.in.block=false;
 if(SEL.open){selInput(dt);return;}
 if(CAMMENU.open){return;}
 if(CAM.view===5&&p0.on&&M.mode==='FIGHT'){CAM.yaw-=p0.ax[2]*2.2*dt;CAM.pitch=clamp(CAM.pitch+p0.ax[3]*1.6*dt,.02,1.3);}
 if(M.mode==='TPS'&&p0.on){CAM.yaw-=p0.ax[2]*2.4*dt;CAM.pitch=clamp(CAM.pitch+p0.ax[3]*1.8*dt,-.08,1.25);}
 // P1 = keyboard/touch merged with pad 0
 const s1={mx:0,my:0,block:false,press:{}};
 s1.mx=(KEY.KeyD?1:0)-(KEY.KeyA?1:0);s1.my=(KEY.KeyW?1:0)-(KEY.KeyS?1:0);s1.block=!!(KEY.KeyL||KEY.ShiftLeft)||TOUCH.block;
 if(TOUCH.joy.on){s1.mx+=TOUCH.joy.x;s1.my+=TOUCH.joy.z;}
 for(const k in kbP1){if(kbP1[k]){s1.press[k]=1;kbP1[k]=0;}}
 if(p0.on){const dpx=(p0.btn[15]?1:0)-(p0.btn[14]?1:0),dpy=(p0.btn[12]?1:0)-(p0.btn[13]?1:0);
