 for(const l of R.legs){const rx=T.pos[0]+l.side*l.fx*sc*cy+l.fz*sc*sy,rz=T.pos[2]-l.side*l.fx*sc*sy+l.fz*sc*cy;
  if(!R.init){l.foot=[rx,0,rz];}
  const tx=rx+Math.sin(T.yaw)*R.spd*.2,tz=rz+Math.cos(T.yaw)*R.spd*.2;
  if(l.on){l.s+=dt/clamp(.34/(1+R.spd*.12),.1,.3);if(l.s>=1){l.on=false;l.foot=l.to.slice();if(sc>1.5&&Math.random()<.3)burst([l.foot[0],.05,l.foot[2]],3,2,[.4,.35,.3],[.2,.2,.2],.4,2,-1);}
