  else if(Math.hypot(l.foot[0]-tx,l.foot[2]-tz)>.5*sc&&stepping[1-l.g]===0){l.on=true;l.s=0;l.from=l.foot.slice();l.to=[tx,0,tz];stepping[l.g]++;}}
 R.init=true;R.ph+=R.spd*dt/sc*2.2;}
