 const SA=[],SB=[],SU=[],SW=[],SL=[];
 for(let i=0;i<8;i++){const l=R.legs[i],H=[B[0]+r[0]*l.side*.38*sc+f[0]*l.hz*sc,B[1]-.08*sc+f[1]*l.hz*sc,B[2]+r[2]*l.side*.38*sc+f[2]*l.hz*sc];
  let dx=l.foot[0]-H[0],dy=l.foot[1]-H[1],dz=l.foot[2]-H[2],d=Math.hypot(dx,dy,dz);const L1=SP_L1*sc,L2=SP_L2*sc,mx=L1+L2-.02*sc;let F2=l.foot;
  if(d>mx){const k=mx/d;dx*=k;dy*=k;dz*=k;d=mx;F2=[H[0]+dx,H[1]+dy,H[2]+dz];}
  const n=[dx/d,dy/d,dz/d],aa=(L1*L1-L2*L2+d*d)/(2*d),h=Math.sqrt(Math.max(0,L1*L1-aa*aa)),dt=n[1];let pp=[-n[0]*dt,1-n[1]*dt,-n[2]*dt];const pl=Math.hypot(pp[0],pp[1],pp[2])||1;pp=[pp[0]/pl,pp[1]/pl,pp[2]/pl];
  const K=[H[0]+n[0]*aa+pp[0]*h,H[1]+n[1]*aa+pp[1]*h,H[2]+n[2]*aa+pp[2]*h];
  for(const [a,b] of [[H,K],[K,F2]]){const v=[b[0]-a[0],b[1]-a[1],b[2]-a[2]],L=Math.hypot(v[0],v[1],v[2])||1,ax=[v[0]/L,v[1]/L,v[2]/L];let uu=[ax[2],0,-ax[0]];let ul=Math.hypot(uu[0],uu[2]);if(ul<.01){uu=[1,0,0];ul=1;}uu=[uu[0]/ul,0,uu[2]/ul];
   const ww=[ax[1]*uu[2]-ax[2]*uu[1],ax[2]*uu[0]-ax[0]*uu[2],ax[0]*uu[1]-ax[1]*uu[0]];SA.push(a);SB.push(v);SU.push(uu);SW.push(ww);SL.push(L);}}
 const fl=A.flash,fz=A.freeze>0,dd=A.dead?A.dt:0,al=A.dead?Math.max(0,1-dd/1.5):1,sz=cls.ps*(.7+.3*Math.sqrt(sc));let o=_spN*8;
 for(let k=0;k<N;k++){const sg=tp.seg[k],q=k*4,a0=tp.a[q],a1=tp.a[q+1],a2=tp.a[q+2],a3=tp.a[q+3];let x,y,z;
  if(sg<3){const c=cen[sg],s2=sg===1?br:1,lx=a0*sc*s2,ly=a1*sc*s2,lz=a2*sc*s2;x=c[0]+r[0]*lx+u[0]*ly+f[0]*lz;y=c[1]+u[1]*ly+f[1]*lz;z=c[2]+r[2]*lx+u[2]*ly+f[2]*lz;}
  else{const si=sg-3,A0=SA[si],V=SB[si],t=a0,rr=a3*sc;x=A0[0]+V[0]*t+(SU[si][0]*a1+SW[si][0]*a2)*rr;y=A0[1]+V[1]*t+(SU[si][1]*a1+SW[si][1]*a2)*rr;z=A0[2]+V[2]*t+(SU[si][2]*a1+SW[si][2]*a2)*rr;}
  if(dd>0){const g=dd*dd*3;x+=(tp.a[q]*dd*2.5);z+=(tp.a[q+2]*dd*2.5);y=Math.max(.05,y-g*.5+Math.abs(tp.a[q+1])*dd*1.5);}
  let cr=tp.col[k*3],cg=tp.col[k*3+1],cb=tp.col[k*3+2];
  if(fl>0){cr+=fl*1.6;cg+=fl*.3;cb+=fl*.3;}if(fz){cr*=.5;cg=cg*.8+.25;cb=cb*.8+.9;}
  _SA[o]=x;_SA[o+1]=y;_SA[o+2]=z;_SA[o+3]=cr;_SA[o+4]=cg;_SA[o+5]=cb;_SA[o+6]=al;_SA[o+7]=sz;o+=8;}
 _spN+=N;}
function drawSpiders(VP){if(!OW.active||!OW.SP.length)return;_spN=0;for(const e of OW.SP)spiderCloud(e);if(!_spN)return;
 if(!spVbo)spVbo=gl.createBuffer();const P=prog.pts;gl.useProgram(P.p);gl.uniformMatrix4fv(P.u.uVP,false,VP);gl.uniform3fv(P.u.uCam,CAM.eye);gl.uniform1f(P.u.uPt,DPRV);
 gl.bindBuffer(gl.ARRAY_BUFFER,spVbo);gl.bufferData(gl.ARRAY_BUFFER,_SA.subarray(0,_spN*8),gl.DYNAMIC_DRAW);
 bindA(P.a.aP,spVbo,3,32,0);bindA(P.a.aC,spVbo,4,32,12);bindA(P.a.aS,spVbo,1,32,28);gl.drawArrays(gl.POINTS,0,_spN);
 gl.disableVertexAttribArray(P.a.aP);gl.disableVertexAttribArray(P.a.aC);gl.disableVertexAttribArray(P.a.aS);}
function drawDrones(VP){const P=prog.fxc;gl.useProgram(P.p);gl.uniformMatrix4fv(P.u.uVP,false,VP);gl.uniform3fv(P.u.uCam,CAM.eye);gl.uniform1f(P.u.uPt,DPRV);gl.uniform1f(P.u.uTime,world.t);bindA(P.a.aA,fxcVbo,4);
 for(const b of OW.SPB)drawFXC(VP,{mode:2,pos:b.p,r:b.r,h:0,t:0,a:1,c1:b.c1,c2:b.c2,n:b.n});
 for(const c of OW.crystals){if(c.hide>0)continue;drawFXC(VP,{mode:2,pos:[c.x,1.3+Math.sin(c.b)*.2,c.z],r:.4,h:0,t:0,a:1,c1:[.2,1.6,.6],c2:[1.6,1.9,1.2],n:3000});}
 gl.disableVertexAttribArray(P.a.aA);}
// ---- game logic ----
function owCrystalPos(c,near){let x,z;if(near){const a=Math.random()*6.28,r=rnd(40,90);x=Math.cos(a)*r;z=Math.sin(a)*r;}else{const a=Math.random()*6.28,r=Math.sqrt(Math.random())*OW.CRYSTAL_SPAWN_RADIUS;x=Math.cos(a)*r;z=Math.sin(a)*r;}c.x=x;c.z=z;c.hide=0;}
OW.enter=function(){OW.active=true;for(const e of OW.SP.slice())owRemove(e);OW.SPB.length=0;OW.wave=0;OW.wt=2.5;OW.kills=0;OW.pInv=0;
 const F=world.entities[0].get('Fighter');F.max=OW.START_HP;F.hp=OW.START_HP;F.en=60;F.sword=0;M.state='fight';
 OW.crystals=[];for(let i=0;i<OW.CRYSTAL_COUNT;i++){const c={x:0,z:0,b:Math.random()*6,hide:0};owCrystalPos(c,i<2);OW.crystals.push(c);}
 CRY.on=false;CRY.next=rnd(8,14);owHud();statusMsg('OPEN WORLD · WASD MOVE · J/K PUNCH/KICK · U/I POWERS · FIND GREEN CRYSTALS (+'+OW.CRYSTAL_HP+' HP)');};
OW.leave=function(){OW.active=false;for(const e of OW.SP.slice())owRemove(e);OW.SPB.length=0;if(OW.hud)OW.hud.g.style.display='none';};
function owRemove(e){const i=OW.SP.indexOf(e);if(i>=0)OW.SP.splice(i,1);const j=world.entities.indexOf(e);if(j>1)world.entities.splice(j,1);}
function owHud(){if(OW.hud)return;const root=$('viewport'),g=el('g',{'pointer-events':'none'},root);
 const bg=el('rect',{x:440,y:12,width:400,height:12,rx:4,fill:'rgba(0,0,0,.55)',stroke:'rgba(0,255,208,.4)'},g),fill=el('rect',{x:440,y:12,width:400,height:12,rx:4,fill:'#33ff99'},g);
 const t1=el('text',{x:640,y:42,'text-anchor':'middle',class:'stat'},g),t2=el('text',{x:640,y:60,'text-anchor':'middle',class:'amb'},g);OW.hud={g:g,fill:fill,t1:t1,t2:t2};}
function owSpawnWave(){OW.wave++;const b=WAVES[Math.min(OW.wave-1,WAVES.length-1)],ex=Math.max(0,OW.wave-WAVES.length),T=world.entities[0].get('Transform');
 const want={giant:b.g+(ex>>1),striker:b.m+ex,swarm:b.s+ex*2};let total=0;
 for(const key of['giant','striker','swarm']){const n=Math.min(want[key],Math.max(0,OW.MAX_ALIVE-total));total+=n;const base=Math.random()*6.28;
  for(let i=0;i<n;i++){const a=base+(key==='swarm'?(i%4)*.35+ (i>>2)*1.6:i/Math.max(1,n)*6.28),r=key==='giant'?rnd(50,70):rnd(38,58);createSpider(key,clamp(T.pos[0]+Math.cos(a)*r,-OW.WORLD_R,OW.WORLD_R),clamp(T.pos[2]+Math.sin(a)*r,-OW.WORLD_R,OW.WORLD_R));}}
 statusMsg('WAVE '+OW.wave+' · '+want.giant+' GIANT · '+want.striker+' STRIKER · '+want.swarm+' SWARM');}
function owPickTarget(T){let best=null,bd=OW.LOCK_RANGE;for(const e of OW.SP){const A=e.get('SpiderAI');if(A.dead)continue;const p=e.get('Transform').pos,d=Math.hypot(p[0]-T.pos[0],p[2]-T.pos[2])-A.cls.sc;if(d<bd){bd=d;best=e;}}return best;}
function hurtSpider(e,dmg,kx,kz,frz){const H=e.get('Health'),A=e.get('SpiderAI'),T=e.get('Transform');if(A.dead)return;H.hp-=dmg;A.flash=1;A.stun=.18;A.kx=kx*.6;A.kz=kz*.6;if(frz>0)A.freeze=frz;
 burst([T.pos[0],A.cls.sc*1.2,T.pos[2]],10,5,[1.6,.3,.3],[1,1,1],.35,3,3);
 if(H.hp<=0){A.dead=true;A.dt=0;OW.kills++;burst([T.pos[0],A.cls.sc*1.2,T.pos[2]],70,9,[1.2,.2,1.6],[.4,.1,1],.9,3.5,1);CAM.shake=Math.max(CAM.shake,A.cls.sc>1.5?.3:.1);
  world.entities[0].get('Fighter').en=Math.min(100,world.entities[0].get('Fighter').en+(A.cls.sc>1.5?25:6));}}
function hurtPlayer(dmg,fx,fz){const e=world.entities[0],F=e.get('Fighter'),T=e.get('Transform');if(OW.pInv>0||F.hp<=0)return;
 if(F.block&&F.state==='free'){dmg*=.15;burst([T.pos[0],T.pos[1]+1.1*F.S,T.pos[2]],12,4,[.3,.8,1.6],[.6,1.2,2],.3,3,0);}
 else{F.flash=1;burst([T.pos[0],T.pos[1]+1.1*F.S,T.pos[2]],16,6,[1.5,.4,1.2],[1,1,1],.4,3,3);CAM.shake=Math.max(CAM.shake,.1+dmg*.004);
  if(dmg>=25&&F.state!=='atk'){F.state='hit';F.st=0;F.stun=.28;F.mv=null;const l=Math.hypot(T.pos[0]-fx,T.pos[2]-fz)||1;F.vx=(T.pos[0]-fx)/l*3;F.vz=(T.pos[2]-fz)/l*3;}}
 F.hp=Math.max(0,F.hp-dmg);OW.pInv=.15;}
function updateTPS(dt,w){const e=w.entities[0],px=w.entities[1],T=e.get('Transform'),F=e.get('Fighter'),T1=px.get('Transform'),F1=px.get('Fighter');
 if(!OW.active)OW.enter();M.state='fight';F.slot=0;F1.slot=1;OW.pInv-=dt;
 const fire=!!INPUTLOOK.fire;if(fire&&!OW._pf)F.in.press.punch=1;OW._pf=fire;
 const tg=owPickTarget(T);
 if(tg){const p=tg.get('Transform').pos;T1.pos=[p[0],0,p[2]];F1.S=tg.get('SpiderAI').cls.sc*.9;}
 else{T1.pos=[T.pos[0]-Math.sin(CAM.yaw)*40,0,T.pos[2]-Math.cos(CAM.yaw)*40];F1.S=1;}
 F1.hp=F1.max=1e9;F1.state='free';F1.y=0;F1.air=false;F1.inv=0;F1.block=false;F1.vx=F1.vz=0;F1.freeze=F1.slow=0;
 updateFighter(e,px,dt,true);
 const dmg=1e9-F1.hp;if(dmg>0&&tg){const l=Math.hypot(F1.vx,F1.vz)||1;hurtSpider(tg,dmg,F1.vx,F1.vz,F1.freeze);if(F1.slow>0)tg.get('SpiderAI').freeze=Math.max(tg.get('SpiderAI').freeze,F1.slow);}
 F1.hp=1e9;F1.state='free';F1.freeze=F1.slow=0;
 if(F.state==='free'&&!F.air){const k=OW.MOVE_BOOST-1;T.pos[0]+=F.vx*dt*k;T.pos[2]+=F.vz*dt*k;if(!tg&&Math.hypot(F.vx,F.vz)>.3)T.yaw=lerpAngle(T.yaw,Math.atan2(F.vx,F.vz),Math.min(1,dt*10));}
 const r=Math.hypot(T.pos[0],T.pos[2]);if(r>OW.WORLD_R){T.pos[0]*=OW.WORLD_R/r;T.pos[2]*=OW.WORLD_R/r;}
 F.en=Math.min(100,F.en+3*dt);
 for(let i=0;i<3;i++)emit([T.pos[0]+rnd(-25,25),.03,T.pos[2]+rnd(-25,25)],[0,rnd(.2,.8),0],[.2,.9,.8],rnd(1.5,3),2,0,0); // ground motes: speed reference in the vast world
 updateExtras(dt,w);
 // HP crystals
 for(const c of OW.crystals){c.b+=dt*2;if(c.hide>0){c.hide-=dt;if(c.hide<=0)owCrystalPos(c,false);continue;}
  const d=Math.hypot(c.x-T.pos[0],c.z-T.pos[2]);
  if(d<2.4){F.max=Math.max(F.max,F.hp+OW.CRYSTAL_HP);F.hp+=OW.CRYSTAL_HP;c.hide=OW.CRYSTAL_RESPAWN;burst([c.x,1.3,c.z],110,9,[.2,1.6,.6],[1.6,1.9,1.2],.9,3.4,0);CAM.shake=Math.max(CAM.shake,.12);statusMsg('◆ HP CRYSTAL +'+OW.CRYSTAL_HP+' HP ◆');}
  else if(d<140&&Math.random()<.5)emit([c.x+rnd(-.3,.3),rnd(1,10),c.z+rnd(-.3,.3)],[0,rnd(1,3),0],[.3,1.6,.8],1,2.6,.3,0);}
 if(F.hp<=0){statusMsg('DOWNED · WAVE RESTARTS');F.hp=OW.START_HP;F.max=Math.max(F.max,OW.START_HP);T.pos=[0,0,0];F.state='free';for(const s of OW.SP.slice())owRemove(s);OW.SPB.length=0;OW.wave=Math.max(0,OW.wave-1);OW.wt=4;}}
function tpsShoot(){}function tpsReload(){}
function owBolt(e,A,P,Pv){const T=e.get('Transform'),cls=A.cls,a=cls.atk,sc=cls.sc,mz=[T.pos[0]+Math.sin(T.yaw)*.9*sc,e.get('SpiderRig').bodyY*e.get('SpiderRig').h+.1*sc,T.pos[2]+Math.cos(T.yaw)*.9*sc],d=Math.hypot(P[0]-mz[0],P[2]-mz[2]),tt=d/a.speed*.6;
 const tgt=[P[0]+Pv[0]*tt,P[1]+1.1,P[2]+Pv[1]*tt],v=V3.scale(V3.norm(V3.sub(tgt,mz)),a.speed);
 OW.SPB.push({p:mz,v:v,dmg:a.dmg,r:a.r*(sc>1.5?1:1),life:3.2,c1:a.c1,c2:a.c2,n:a.n,from:[T.pos[0],T.pos[2]]});burst(mz,10,4,a.c1,a.c2,.3,3,0);}
function spiderSystem(dt,w){if(M.mode!=='TPS'||!OW.active){if(OW.hud)OW.hud.g.style.display='none';return;}
 const pe=w.entities[0],PT=pe.get('Transform'),PF=pe.get('Fighter'),P=[PT.pos[0],PT.pos[1],PT.pos[2]],Pv=[PF.vx,PF.vz];
 let giants=0,alive=0;for(const e of OW.SP){const A=e.get('SpiderAI');if(!A.dead){alive++;if(A.key==='giant')giants++;}}
 if(alive===0){OW.wt-=dt;if(OW.wt<=0){owSpawnWave();OW.wt=OW.WAVE_PAUSE;}}
 for(const e of OW.SP.slice()){const T=e.get('Transform'),R=e.get('SpiderRig'),A=e.get('SpiderAI'),cls=A.cls;
  if(A.dead){A.dt+=dt;if(A.dt>1.5)owRemove(e);continue;}
  A.cd-=dt;A.cd2-=dt;A.flash=Math.max(0,A.flash-dt*4);A.stun-=dt;A.freeze-=dt;A.lunge=Math.max(0,A.lunge-dt*3);A.st-=dt;if(A.st<=0){A.st=rnd(2,4);A.strafe*=-1;}
  const dx=P[0]-T.pos[0],dz=P[2]-T.pos[2],d=Math.hypot(dx,dz)||1,toP=Math.atan2(dx,dz);let want=0,hv=1,crouch=1;
  const active=cls.behave!=='lurk'||giants<=OW.GIANTS_LOW;
  if(!active){hv=.15;crouch=.45;want=0;A.mode='lurk';}
  else if(cls.atk){const a=cls.atk;
   if(A.charge>0){A.charge-=dt;hv=.1;R.pitch+=(.5-R.pitch)*Math.min(1,dt*10);if(A.charge<=0){owBolt(e,A,P,Pv);A.cd=a.cd;}}
   else{R.pitch+=(0-R.pitch)*Math.min(1,dt*6);
    if(d>a.range){A.mode='chase';want=1;}else if(d<a.min*cls.sc*.5||(d<a.min)){A.mode='retreat';want=-.8;}else{A.mode='strafe';want=.25;}
    if(A.cd<=0&&d<a.range&&d>cls.sc*1.5)A.charge=a.wind;
    if(d<cls.sc*1.9+.8&&A.cd2<=0){A.cd2=cls.melee.cd;A.lunge=1;hurtPlayer(cls.melee.dmg,T.pos[0],T.pos[2]);}}}
  else{A.mode='rush';want=d>cls.sc*1.4?1:0;crouch=.8;if(d<cls.sc*1.6+.7&&A.cd2<=0){A.cd2=cls.melee.cd;A.lunge=1;hurtPlayer(cls.melee.dmg,T.pos[0],T.pos[2]);}}
  const sl=A.freeze>0?.4:1,stun=A.stun>0?0:1;let ha=toP;if(A.mode==='strafe')ha=toP+A.strafe*1.4;else if(A.mode==='retreat')ha=toP+Math.PI;
  T.yaw=lerpAngle(T.yaw,A.mode==='strafe'||A.mode==='retreat'||A.charge>0?toP:ha,Math.min(1,dt*5));
  const sp=cls.spd*(want===0?0:Math.abs(want))*hv*sl*stun;R.spd+=(sp-R.spd)*Math.min(1,dt*5);
  const mvx=Math.sin(ha)*(want<0?1:Math.sign(want||1)),mvz=Math.cos(ha)*(want<0?1:Math.sign(want||1));
  T.pos[0]+=mvx*R.spd*dt+A.kx*dt;T.pos[2]+=mvz*R.spd*dt+A.kz*dt;A.kx*=Math.max(0,1-dt*6);A.kz*=Math.max(0,1-dt*6);
  for(const o of OW.SP){if(o===e)continue;const q=o.get('Transform').pos,ox=T.pos[0]-q[0],oz=T.pos[2]-q[2],od=Math.hypot(ox,oz),mn=(cls.sc+o.get('SpiderAI').cls.sc)*.55;if(od<mn&&od>.001){T.pos[0]+=ox/od*(mn-od)*.3;T.pos[2]+=oz/od*(mn-od)*.3;}}
  const mind=cls.sc*.9+.5;if(d<mind){T.pos[0]-=dx/d*(mind-d)*.5;T.pos[2]-=dz/d*(mind-d)*.5;}
  R.h+=(crouch-R.h)*Math.min(1,dt*4);if(A.charge<=0)R.pitch+=(-A.lunge*.25-R.pitch)*Math.min(1,dt*8);
  spiderGait(e,dt);}
 for(let i=OW.SPB.length-1;i>=0;i--){const b=OW.SPB[i];b.life-=dt;b.p[0]+=b.v[0]*dt;b.p[1]+=b.v[1]*dt;b.p[2]+=b.v[2]*dt;
  emit(b.p,[rnd(-1,1),rnd(-1,1),rnd(-1,1)],b.c1,.35,2.6,2,0);
  const pd=Math.hypot(b.p[0]-P[0],b.p[1]-(P[1]+1.1*PF.S),b.p[2]-P[2]);
  if(pd<b.r+.7*PF.S){hurtPlayer(b.dmg,b.from[0],b.from[1]);burst(b.p,24,7,b.c1,b.c2,.5,3.4,0);OW.SPB.splice(i,1);}
  else if(b.life<=0||b.p[1]<.05){burst(b.p,12,5,b.c1,b.c2,.4,3,0);OW.SPB.splice(i,1);}}
 // HUD
 const h=OW.hud;if(h){h.g.style.display='';h.fill.setAttribute('width',(400*clamp(PF.hp/PF.max,0,1)).toFixed(1));
  h.t1.textContent='HP '+Math.ceil(PF.hp)+'/'+Math.ceil(PF.max)+' · EN '+Math.floor(PF.en)+' · WAVE '+OW.wave+' · KILLS '+OW.kills+' · '+alive+' SPIDERS';
  let bc=null,bd=1e9;for(const c of OW.crystals){if(c.hide>0)continue;const dd=Math.hypot(c.x-PT.pos[0],c.z-PT.pos[2]);if(dd<bd){bd=dd;bc=c;}}
  if(bc){const rel=wrapAng(CAM.yaw+Math.PI-Math.atan2(bc.x-PT.pos[0],bc.z-PT.pos[2])),idx=(Math.round(rel/(Math.PI/4))+8)%8;h.t2.textContent='◆ HP CRYSTAL '+['↑','↗','→','↘','↓','↙','←','↖'][idx]+' '+Math.round(bd)+'m';}else h.t2.textContent='';}}
OW.followVP=function(VP){const g=new Float32Array(VP),T=world.entities[0].get('Transform').pos;for(let i=0;i<4;i++)g[12+i]=VP[12+i]+VP[i]*T[0]+VP[8+i]*T[2];return g;};

function boot(){
 world=new World();
 makeFighter(world,'operator','op',0);makeFighter(world,'rival',ARCH_KEYS[1],1);
 world.create('camera').add(new C('OrbitCam',{}));world.create('skybox').add(new C('Sky',{}));world.create('arena').add(new C('WorldCloud',{}));
 sys('IN',sysInput,true);sys('FIGHT',sysFight);sys('PROJ',function(dt){updateProj(dt);updateGFX(dt);});sys('FX',function(dt){stepFX(dt);});
 sys('ANIM',sysAnim);sys('SPIDERS',spiderSystem);sys('TOD',function(dt){if(TOD.auto)TOD.hour+=dt*.35;updateTOD();},true);sys('CAM',updateCamera,true);sys('RENDER',sysRender,true);sys('HUD',sysHUD,true);
 let ok=true;try{initGL();}catch(err){ok=false;console.error(err);}
 doResize();window.addEventListener('resize',doResize);attachInput();updateTOD();
 if(ok){setArch(world.entities[0],'op');setArch(world.entities[1],ARCH_KEYS[1]);}else statusMsg('WEBGL UNAVAILABLE');
 startRound();openSel();
 window.__FIGHT={world:world,M:M,CAM:CAM,TOD:TOD,TPS:TPS};
 requestAnimationFrame(loop);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
